(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).de={"nav.skip":"Zum Inhalt springen","nav.main":"Hauptnavigation","nav.menu":"Menü","nav.close":"Schließen","nav.lang":"Sprache","nav.tick":"Block","nav.tick.title":"Der neueste Block. Zur Live-Seite des Netzes.","cta.join":"Mitmachen","nav.g.part":"Mitmachen","nav.g.know":"Verstehen","nav.g.join":"Dabei sein","nav.start":"Womit anfangen","nav.start.d":"Fünf Wege hinein, jeder mit seinem ersten Schritt","nav.mine":"Mining","nav.mine.d":"Blöcke finden mit Handy, PC oder Grafikkarte","nav.wallet":"Wallet","nav.wallet.d":"Zwölf Wörter, die nur du hast","nav.node":"Knoten betreiben","nav.node.d":"Jeden Block selbst prüfen","nav.ysr":"YSR","nav.ysr.d":"21 Millionen, jeder einzelne geschürft","nav.chain":"Die Kette","nav.chain.d":"Eine eigene Blockchain und wie sie sich beweist","nav.network":"Netz, live","nav.network.d":"Was die Kette gerade tut","nav.explorer":"Explorer","nav.explorer.d":"Jeder Block, jede Überweisung, jede Adresse","nav.community":"Community","nav.community.d":"Wo das Projekt redet und entscheidet","nav.build":"Entwickeln","nav.build.d":"Offener Code, öffentliche API, Vorschläge","nav.story":"Geschichte und nächste Schritte","nav.story.d":"Von Block 0 bis heute, und was danach kommt","foot.claim":"Fair von Block 0 an.","foot.sub":"YSKAR ist ein Community-Projekt. Dahinter steht kein Unternehmen, und niemandem muss man glauben: Jeder Block lässt sich nachprüfen.","foot.nav":"Alle Seiten","foot.whitepaper":"Whitepaper","foot.find":"YSKAR finden","foot.imprint":"Impressum","foot.privacy":"Datenschutz","foot.license":"Open Source unter der MIT-Lizenz","title.home":"Fair von Block 0 an","title.start":"Womit anfangen","title.mine":"Mining","title.wallet":"YSKAR Wallet","title.node":"Knoten betreiben","title.ysr":"YSR, die Münze","title.chain":"Die Kette","title.network":"Netz, live","title.explorer":"Explorer","title.build":"Auf YSKAR entwickeln","title.community":"Community","title.story":"Geschichte und nächste Schritte","ui.copied":"Kopiert","ui.copy":"Kopieren","ui.sample":"Der Bildschirm zeigt Beispieldaten.","dawn.h":"Hier ist es noch früh.","dawn.p":"Tag <span data-live='day'></span>. Über diesem Netz wird es gerade erst hell. Wer es prägt, entscheidet sich jetzt: mit denen, die da sind.","dawn.cta2":"Die Geschichte bis heute","dawn.alt":"Derselbe Fjord im ersten Licht: heller Himmel über verschneiten Bergen und stillem Wasser.","nav.guides":"Anleitungen","nav.guides.d":"Jeder Weg zum Mitmachen, Schritt für Schritt","nav.protocol":"Protokoll","nav.protocol.d":"Münze, Kette und Wallets, Byte für Byte","nav.paper.d":"Das System, wie es umgesetzt ist","title.guides":"Anleitungen","title.protocol":"Protokoll","title.paper":"Whitepaper","title.imprint":"Impressum","title.privacy":"Datenschutz","doc.toc":"Auf dieser Seite","foot.live":"Die Zahlen auf diesen Seiten kommen live aus der öffentlichen YSKAR-API.","foot.stale":"Die öffentliche YSKAR-API antwortet gerade nicht. Diese Seiten zeigen die Kette, wie sie am {date} stand (Block {h}), und holen den neuen Stand von selbst nach.","title.notfound":"Seite nicht gefunden","nf.h":"Diese Seite gibt es nicht.","nf.p":"Vielleicht ist der Link vertippt, oder die Seite ist umgezogen. Die Kette selbst ist, wo sie war.","nf.home":"Zur Startseite","nf.explorer":"Im Explorer nachschlagen","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR ist eine Währung mit eigener Blockchain. Nichts wurde vorab verteilt: Jeder YSR wird geschürft, und jeden Block kann jeder nachprüfen. Fair von Block 0 an.","home.hero.cta2":"Die Kette bis heute ansehen","home.hero.live":"Tag {d} · Block {h} · {n} Lichter am Ufer, eines für jeden Knoten, der sich gemeldet hat","home.hero.alt":"Ein dunkler Fjord zwischen verschneiten Bergen unter einem Sternenhimmel. Darüber ziehen Bänder aus blauem Licht, am fernen Ufer leuchten kleine warme Lichter.","home.m1":"Am Anfang stand kein Versprechen. Am Anfang stand ein Block.","home.m2":"Nichts wurde vorab erzeugt, nichts verteilt. Rund 1,07 Millionen YSR aus der Anfangszeit wurden verbrannt, um den Vorsprung auszugleichen.","home.m3":"Seitdem entsteht ein neuer YSR nur auf einem Weg: Eine Maschine leistet die Arbeit, und jeder kann sie nachprüfen.","walk.start.h":"<span data-live='day'></span> Tage, Block für Block.","walk.start.p":"Jedes Licht ist ein echter Block, der Abstand zwischen zwei Lichtern ist die Zeit dazwischen. Scroll die Kette entlang. Tipp ein Licht an, um seinen Block zu öffnen.","walk.c0.h":"Es beginnt mit einem Block.","walk.c0.p":"Seine einzige Nachricht: „proof, not promise“. Seine Belohnung von 875 YSR ging an eine Adresse, von der niemand etwas ausgeben kann.","walk.c1.h":"Tag eins: 46 Blöcke.","walk.c1.p":"Der erste Block nach Block 0 kam um 18:03 Uhr UTC. Bis Mitternacht waren es 46: Die Kette hatte ihren Takt gefunden.","walk.c3.h":"Der Vorsprung wird verbrannt.","walk.c3.p":"1.066.101 YSR aus der Anfangszeit gehen an die Adresse, von der niemand etwas ausgeben kann, um den Vorsprung auszugleichen. Alles steht in diesem Block.","walk.c4.h":"Die Community stimmt ab.","walk.c4.p":"Über Fassung 6 wird offen entschieden: gemeinsame Konten, Zeitsperren, Zahlungen an tausend Empfänger auf einmal. Drei Regelfassungen waren da schon aktiv.","walk.c5.h":"Hier stehst du.","walk.c5.p":"Der nächste Block ist ungefähr zehn Minuten entfernt.","walk.c6.h":"Als Nächstes: Fassung 6 wird aktiv.","walk.c6.p":"In <span data-live='v6Left'></span> Blöcken. Jeder Knoten kennt die Höhe im Voraus, nichts ändert sich überraschend.","walk.c6.h.past":"Fassung 6 ist aktiv.","walk.c6.p.past":"Seit Block 10.000 kennt die Kette gemeinsame Konten, Zeitsperren und Sammelzahlungen.","walk.c7.h":"Dann endet die erste Epoche.","walk.c7.p":"Bis Block 12.000 erzeugt jeder Block 875 YSR, danach 437,5. Die Hälfte aller YSR, die es je geben wird, entsteht in dieser ersten Epoche.","walk.c7.h.past":"Die erste Epoche ist vorbei.","walk.c7.p.past":"Seit Block 12.000 erzeugt jeder Block 437,5 YSR. Die Belohnung halbiert sich alle 12.000 Blöcke wieder.","walk.open":"Diesen Block öffnen","walk.k.block":"Block {h} · {d}","walk.k.future":"Block {h} · kommt noch","home.walk.now":"Block {h} · Tag {d}","walk.hud.block":"Block {h}","walk.hud.ahead":"Block {h}","walk.hud.planned":"kommt noch · im Code festgelegt","walk.hud.day":"Tag {n}","walk.tip.block":"Block {h}","walk.tip.approx":"Einzelheiten zeigt der Explorer","walk.tip.solo":"Von einem einzelnen Miner gefunden","walk.tip.pool":"Von einem Pool gefunden","walk.tip.tx":"mit Überweisungen","walk.legend.block":"ein Block","walk.legend.tx":"ein Block mit Überweisungen","walk.canvas":"Die Kette als Band aus Lichtern, ein Licht für jeden Block seit Block 0.","home.proof.h":"Glaub uns kein Wort.","home.proof.p":"Jeder Block trägt seinen Beweis in sich. Dein Gerät kann ihn jetzt nachrechnen: ohne Server, ohne Konto, nur mit Rechnen.","prove.btn.genesis":"Block 0 auf diesem Gerät prüfen","prove.btn.tip":"Den neuesten Block prüfen","prove.label":"Hash des Blockkopfs","prove.ok":"Gültig. Block {h} wurde auf diesem Gerät geprüft, in {ms} ms.","prove.bad":"Ungültig: Block {h} verfehlt sein Ziel.","prove.open":"Block {h} im Explorer öffnen","prove.note":"Was dein Gerät gerade getan hat: Es hat die 136 Byte des Blockkopfs zweimal mit SHA-256 gerechnet. Das Ergebnis muss kleiner sein als das Ziel, das das Netz für diesen Block vorgibt. Die Nullen am Anfang zeigen, wie klein es ist.","home.ways.h":"Drei Wege hinein.","home.ways.p":"Das Zeichen von YSKAR sind drei Bänder, die sich treffen. Das Netz ist es auch: Menschen, die schürfen, Menschen, die halten und senden, und Menschen, die einen Knoten laufen lassen.","way.mine.h":"Leih ihm deine Maschine.","way.mine.p":"Ein Handy, ein PC oder eine Grafikkarte können Blöcke finden. Allein oder in einem Pool, der dich direkt im Block bezahlt und deine Coins nie verwahrt.","way.mine.cta":"So funktioniert Mining","way.mine.alt":"Ein Laptop auf einem Holztisch bei Nacht, darauf läuft YSKAR Node Core; dahinter ein Fenster zum dunklen Fjord.","way.wallet.h":"Zwölf Wörter. Nur deine.","way.wallet.p":"Deine Wallet liegt auf deinem eigenen Gerät. Niemand sonst hat deine Schlüssel, auch nicht die Menschen, die YSKAR bauen.","way.wallet.cta":"Zur Wallet","way.wallet.alt":"Ein Handy mit geöffneter YSKAR Wallet auf einem dunklen Holztisch, daneben ein Notizbuch mit zwölf handgeschriebenen Zeilen, ein Stift und eine Tasse Tee.","way.node.h":"Lass ein Licht an.","way.node.p":"Ein Knoten prüft jeden Block selbst, ab Block 0. Jeder einzelne macht das Netz schwerer zu verbiegen. Ein kleiner Rechner auf der Fensterbank genügt.","way.node.cta":"Knoten betreiben","way.node.alt":"Ein kleiner Rechner mit einem türkisen Statuslicht auf einer hölzernen Fensterbank; draußen ein Fjord bei Nacht mit ein paar Lichtern am anderen Ufer.","home.ways.more":"Oder bau darauf. Der Code ist offen, die API öffentlich, und Vorschläge werden dort besprochen, wo jeder mitlesen kann.","home.ways.more.cta":"Für Entwickler","home.early.say":"Tag {d}. {n} Knoten. {m} Miner. {p} Pools. {x} Überweisungen. Kein Listing. Kein Preis. So sieht früh aus.","home.early.note":"Knoten und Miner nach eigener Meldung. Alle Zahlen stammen aus der öffentlichen API.","home.early.p":"Ein kleines Netz, <span data-live='day'></span> Tage alt. YSR ist nirgends gelistet und hat keinen Preis; Listings sind in Vorbereitung, ohne Datum und ohne Namen. Was es heute gibt: eine Kette, die läuft, Software, die du starten kannst, und Platz für alle, die jetzt dazukommen.","home.era.h":"Epoche <span data-live='era'></span>","home.era.p":"In dieser Epoche erzeugt jeder Block <span data-live='rewardNow'></span> YSR. Bei Block <span data-live='halvingHeight'></span> halbiert sich die Belohnung, danach alle 12.000 Blöcke wieder. Die Hälfte aller YSR, die es je geben wird, entsteht in den ersten 12.000 Blöcken. Der Plan steht im Code; niemand kann ihn verschieben.","home.era.now":"Block <span data-live='height'></span>","home.era.left":"noch <span data-live='halvingLeft'></span> Blöcke","home.era.cta":"Der ganze Plan","home.people.h":"Kein Unternehmen. Nur Menschen.","home.people.p":"YSKAR ist ein Community-Projekt und gehört den Menschen, die es nutzen. Sie schürfen, betreiben Knoten, testen Versionen und entscheiden offen über Änderungen: Über Fassung 6 hat die Community abgestimmt.","home.people.cta":"Zur Community","home.people.cta2":"YSKAR Lab öffnen","home.people.alt":"Etwa fünfzehn Menschen von hinten an einem verschneiten Ufer zur blauen Stunde, jeder mit einer kleinen Laterne, den Blick über den Fjord.","start.h1":"Such dir deinen Weg hinein.","start.lead":"Mitmachen kostet nichts. Fang mit dem an, was zu dir passt; dieselben zwölf Wörter öffnen später jede weitere Tür.","start.1.h":"Ich will YSR halten und senden","start.1.p":"Installier die Android-Wallet, schreib zwölf Wörter auf Papier, zeig deine Adresse. Mehr braucht es nicht, um zu empfangen.","start.1.do":"Zur Wallet","start.2.h":"Ich will schürfen","start.2.p":"Fang mit dem Gerät an, das du schon hast: Node Core auf dem PC, die Android-App auf dem Handy, die Kommandozeile auf dem Rig.","start.2.do":"Zum Mining","start.3.h":"Ich will die Kette selbst prüfen","start.3.p":"Betreib einen Knoten. Er prüft jeden Block ab Block 0 und wird ein weiteres Licht am Ufer.","start.3.do":"Knoten betreiben","start.4.h":"Ich will entwickeln oder helfen","start.4.p":"Lies den Code, frag die öffentliche API, teste eine Version, bring einen Vorschlag ins YSKAR Lab.","start.4.do":"Für Entwickler","start.5.h":"Ich will erst einmal zuschauen","start.5.p":"Verfolg die Kette live, öffne jeden Block im Explorer, lies im Kanal mit.","start.5.do":"Das Netz, live","start.safe.h":"Drei Dinge vorab","start.alt.fjord":"Ein dunkler Fjord unter Sternenhimmel.","mine.h1":"Leih ihm deine Maschine.","mine.lead":"Neue YSR entstehen durch Mining und nirgends sonst. Ein Handy, ein PC oder eine Grafikkarte können mitmachen, allein oder in einem Pool.","mine.cta":"Such dir dein Setup aus","mine.cta2":"Gleich hier ausprobieren","mine.try.h":"Mining ist Raten, sehr schnell.","mine.try.p":"Drück auf Start, und dieses Gerät macht einen Moment lang mit. Es nimmt den neuesten Block und sucht eine Zahl, mit der sein Hash mit genug Nullen beginnt: dieselbe Suche wie bei jedem Miner, nur mit Übungsschwierigkeit.","mine.try.go":"Raten starten","mine.try.stop":"Stopp","mine.try.again":"Noch einmal","mine.try.tries":"Versuche","mine.try.speed":"Tempo","mine.try.idle":"Noch nichts gefunden. Jeder Funke ist ein Schwung Versuche.","mine.try.found":"Gefunden, nach {n} Versuchen.","mine.try.none":"Kein Glück in {n} Versuchen. Auch das ist Mining. Versuch es noch einmal.","mine.try.real":"Das war Übung. Das echte Netz ist {x}-mal schwerer: Mit {r} bräuchte dieses Gerät allein etwa {t} für einen echten Block. Darum schließen sich Miner zu Pools zusammen.","mine.try.canvas":"Funken für jeden Schwung Versuche; ein heller Blitz, wenn eine gültige Zahl gefunden ist.","mine.setup.h":"Such dir dein Setup aus","mine.calc.h":"Was könnte deine Maschine finden?","mine.pools.h":"Die Pools, live","wal.h1":"Zwölf Wörter. Nur deine.","wal.lead":"YSKAR Wallet ist die Android-App für YSR: senden, empfangen, signieren. Dein Schlüssel entsteht auf deinem Handy und bleibt dort.","wal.cta2":"In vier Schritten installieren","wal.say":"Wer die zwölf Wörter hat, hat das Guthaben. Schreib sie auf Papier. Niemand von YSKAR wird dich je danach fragen.","node.h1":"Lass ein Licht an.","node.lead":"Ein voller Knoten prüft jeden Block selbst, ab Block 0, und gibt ihn weiter. Er fragt niemanden, was stimmt. Jeder Knoten, der das tut, macht das Netz schwerer zu verbiegen.","node.cta":"Node Core holen","node.cta2":"Über die Kommandozeile","node.say":"Jedes Licht an diesem Ufer ist ein Knoten, der sich gemeldet hat. Gerade sind es {n}. Deiner wäre Nummer {k}.","node.core.h":"Node Core: Knoten, Wallet und Miner in einem Fenster.","node.core.p":"Installieren, und dein Rechner prüft die Kette selbstständig. Node Core hält außerdem deine Wallet, schürft mit Prozessor oder Grafikkarte, kann einen Pool betreiben und signiert Nachrichten. Version 1.1.0 für Windows 10 und 11 und für 64-Bit-Linux.","node.dl.win":"Installer für Windows","node.dl.deb":"Linux-Paket (.deb)","node.dl.app":"Linux-AppImage","node.dl.get":"Laden","node.dl.all":"Alle Dateien und Prüfsummen","node.dl.rel":"Die Veröffentlichung auf GitHub","node.why.h":"Was ein Knoten mehr verändert","node.w1.p":"Dein Knoten rechnet die Arbeit, die Signaturen und jedes Guthaben nach, ab Block 0. Ein Block, der eine Regel bricht, wird abgelehnt, egal von wem er kommt.","node.w2.h":"Er trägt das Netz","node.w2.p":"Jeder Knoten gibt Blöcke und Überweisungen an andere weiter. Je mehr es sind, an je mehr Orten, desto weniger hängt das Netz an einer einzelnen Maschine.","node.w3.h":"Er braucht wenig","node.w3.p":"Über die Kommandozeile läuft ein Knoten unter Linux, Windows und macOS, sogar auf einem Raspberry Pi. Node Core, die Desktop-App, läuft unter Windows und 64-Bit-Linux.","coin.h1":"21 Millionen. Jeder einzelne geschürft.","coin.lead":"YSR ist die Münze der YSKAR-Kette. Mehr als 21.000.000 wird es nie geben. Nichts wurde vorab erzeugt oder verteilt: Ein neuer YSR entsteht aus genau einem Grund, ein Block wurde gefunden.","coin.alt":"Die YSR-Münze: eine dicke Scheibe aus blauem Glas mit erhabenem Rand und dem YSKAR-Zeichen als Relief.","coin.alt.flat":"Die YSR-Münze: eine dunkle Scheibe mit blauem Ring und dem YSKAR-Zeichen.","coin.bar.mined":"bisher geschürft","coin.bar.burned":"davon verbrannt oder unausgebbar","coin.bar.open":"noch zu schürfen","coin.eras.h":"Die Belohnung halbiert sich alle 12.000 Blöcke.","coin.eras.p":"Jeder Balken ist eine Epoche und zeigt, wie viele YSR sie erzeugt. Allein die erste Epoche erzeugt die Hälfte von allem. Der letzte neue YSR entsteht in Block 443.999; danach verdienen Miner nur noch Gebühren.","coin.eras.era":"Epoche {n}","coin.eras.now":"jetzt","coin.eras.rest":"Angaben in YSR. 9+ steht für alle späteren Epochen zusammen.","coin.burn.h":"Der Vorsprung wurde verbrannt.","coin.burn.cta":"In Block 3.974 nachsehen","chain.h1":"Eine eigene Kette.","chain.lead":"YSKAR läuft nicht auf einem anderen Netz. Es hat eigene Blöcke, ein eigenes Peer-to-Peer-Netz und eigene Regeln, und es beweist jeden Block mit Arbeit, die jeder nachprüfen kann.","chain.how.h":"Ein Block, drei Schritte.","chain.why.h":"Warum eine eigene Kette zählt","chain.y1.h":"Ihre Regeln gehören ihr","chain.y1.p":"Über Gebühren, Blockzeiten und Erweiterungen wird hier entschieden, von den Menschen, die YSKAR betreiben, und von keinem fremden Netz.","chain.y2.h":"Nichts, was man glauben muss","chain.y2.p":"Jeder Block bis zurück zu Block 0 lässt sich von jedem nachrechnen, mit offener Software, auf einem gewöhnlichen Rechner.","chain.y3.h":"Änderungen kommen offen","chain.y3.p":"Eine Regeländerung steht im Code, zusammen mit dem Block, ab dem sie gilt. Jeder Knoten kennt ihn im Voraus. Über Fassung 6 hat die Community abgestimmt.","chain.deep.h":"Für Neugierige: wie es im Einzelnen funktioniert","chain.deep.p":"Ab hier wird die Seite technisch. Alles Folgende stammt aus dem Konsens-Code und aus der Kette selbst.","netp.lead":"Was die Kette gerade tut, gelesen aus der öffentlichen API. Nichts hier ist von Hand geschätzt.","bld.h1":"Bau darauf.","bld.lead":"Alles an YSKAR ist offen: Knoten, Wallets, Miner, Explorer und diese Website, unter der MIT-Lizenz. Eine öffentliche API antwortet ohne Schlüssel.","bld.cta":"Die API ausprobieren","bld.cta2":"Der Code auf GitHub","bld.1.h":"Alles lesen","bld.1.p":"Das Protokoll ist beschrieben, der Konsens-Code kurz genug zum Lesen, und jede Zahl auf dieser Website stammt aus diesem Code oder aus der Kette.","bld.2.h":"Die Kette fragen","bld.2.p":"Blöcke, Überweisungen, Adressen, Gebühren, Pools und Menge über schlichtes HTTP. Kein Schlüssel, keine Anmeldung, offen für jede Website.","bld.3.h":"Es verändern","bld.3.p":"Vorschläge laufen über das YSKAR Lab, öffentlich, von der ersten Idee bis zur Veröffentlichung. Angemeldet wird mit der eigenen Wallet.","comm.h1":"Kein Unternehmen. Nur Menschen.","comm.lead":"YSKAR ist ein Community-Projekt und gehört den Menschen, die es nutzen. Hier reden, testen und entscheiden sie.","comm.ch.h":"Wo man alle findet","comm.do.h":"Was du tun kannst. Nichts davon braucht eine Erlaubnis.","comm.lab.h":"Wie aus einem Vorschlag eine Veröffentlichung wird","comm.safe.h":"Bleib sicher","comm.ann":"Bitcointalk","story.h1":"Schritte, keine Termine.","story.lead":"Woher YSKAR kommt, was heute läuft und was als Nächstes kommt. Niemand verspricht hier einen Liefertermin: Änderungen gelten ab einem Block, nicht ab einem Kalendertag.","story.why.h":"Warum es YSKAR gibt","story.why.say":"Das Ziel ist eine Währung, die Menschen im Alltag nutzen können. Zuerst kommt ein solides Fundament. Ein kurzer Hype ist nicht der Plan.","story.why.p":"YSKAR gehört den Menschen, die es nutzen. Deine YSR liegen auf einer Adresse, die nur deine zwölf Wörter öffnen. Niemandem muss man vertrauen: Jeden Block bis zurück zu Block 0 kann jeder nachprüfen. Neue YSR entstehen durch Mining, nie durch ein Versprechen.","story.run.h":"Läuft heute","story.fix.h":"Per Blockhöhe festgelegt","story.plan.h":"Geplant, ohne Termin","story.walk":"Die Kette ab Block 0 entlanggehen","coin.field.alt":"Ein Feld aus Lichtern für alle 21 Millionen YSR: Die bisher geschürften leuchten, die verbrannten glimmen, der Rest ist dunkel.","coin.field.burned":"verbrannt","coin.f0.h":"21.000.000. Mehr werden es nie.","coin.f0.p":"Jedes Licht steht für <span data-field-unit></span> YSR, in der Reihenfolge ihrer Entstehung. Das ist alles, was es je geben wird.","coin.f1.p":"So viele gibt es heute, <span data-live='mintedPct'></span> der Gesamtmenge. Jeder einzelne stammt aus einem Block, den jemand gefunden hat.","coin.f2.p":"Rund 1,07 Millionen YSR aus der Anfangszeit wurden verbrannt, um den Vorsprung auszugleichen. Sie gingen an eine Adresse, von der niemand etwas ausgeben kann, und sind für immer weg.","coin.f3.h":"Die Hälfte kommt zuerst.","coin.f3.p":"Die ersten 12.000 Blöcke erzeugen 10,5 Millionen YSR: die Hälfte von allem, was es je geben wird. Die Kette steht bei Block <span data-live='height'></span>.","coin.f4.h":"Dann halbiert es sich, wieder und wieder.","coin.f4.p":"Alle 12.000 Blöcke halbiert sich die Belohnung. Der letzte neue YSR entsteht in Block 443.999. Danach verdienen Miner nur noch Gebühren.","coin.noprice.say":"YSR hat heute keinen Preis. Es ist nirgends gelistet. Was es hat, ist eine Kette, die jeder nachprüfen kann.","wal.phone.alt":"Ein Handy mit echten Bildschirmen der YSKAR Wallet, einer nach dem anderen.","wal.s1.h":"Dein Guthaben, und nichts davor.","wal.s3.h":"Ein Verlauf für alles.","wal.s3.p":"Zahlungen, Blockbelohnungen und Pool-Anteile stehen an einem Ort. Beträge stimmen bis zur 8. Nachkommastelle.","wal.s5.h":"Namen statt Adressen.","wal.s5.p":"Einmal als Kontakt gespeichert, stehen alle Zahlungen mit dieser Person in einem Verlauf.","pay.alt":"Viele kleine Lichter funkeln, sammeln sich zu einem hellen Punkt, der zum Block wird, und vom Block laufen Strahlen zu jeder Adresse, die er bezahlt.","pay.0.h":"Alle raten gleichzeitig.","pay.0.p":"Gerade arbeitet das ganze Netz mit rund <span data-live='hashrate'></span>: Milliarden Zahlen pro Sekunde, alle auf der Jagd nach demselben Block.","pay.1.h":"Eine Zahl passt.","pay.1.p":"Etwa alle zehn Minuten findet eine Maschine eine Zahl, die passt. Das ist ein neuer Block, und die Suche beginnt von vorn.","pay.2.h":"Der Block bezahlt alle, die geholfen haben.","pay.2.p":"Im Pool wird die Belohnung nach geleisteter Arbeit geteilt und direkt im Block ausgezahlt. Der neueste Pool-Block hat <span id='pay-n'></span> Adressen auf einmal bezahlt.","pay.3.h":"Kein Konto. Keine Auszahlungsschwelle. Keine Verwahrung.","calcx.a":"Meine Maschine schafft","calcx.b":"und ich schürfe","poolsx.last":"der neuesten Blöcke","poolsx.fee":"Gebühr","poolsx.seats":"Plätze belegt","poolsx.rate":"gemeldet","shore.on":"Eines mehr anschalten","shore.off":"Wieder ausschalten","shore.note.on":"Nummer {k} leuchtet nur auf deinem Bildschirm. Es zählt erst, wenn dein Knoten läuft.","node.check.h":"Von Block 0 bis heute, ohne jemanden zu fragen.","comm.vote.say":"Am 25. Oktober 2026 hat die Community abgestimmt, wann Fassung 6 beginnt. Sie hat Block 10.000 gewählt.","comm.vote.cta":"Was Fassung 6 bringt","log.k":"Jeder Block bis","log.cap":"Jede Zeile ist ein Tag seit dem 9. September 2026 (UTC), jeder Strich ein Block zu seiner Uhrzeit. Warme Striche trugen Überweisungen. Tippe einen Strich an, um den Block zu öffnen.","log.cap.n":"Jede Zeile umfasst {d} Tage seit dem 9. September 2026 (UTC), jeder Strich ist ein Block. Warme Striche trugen Überweisungen. Tippe einen Strich an, um den Block zu öffnen.","log.alt":"Das Logbuch der Kette: jeder Block seit Block 0 als Strich, eine Zeile je Tag.","comm.say":"Tag {d}. {n} Knoten halten die Kette, {m} Miner verlängern sie, {p} Pools teilen die Arbeit. Niemand wurde ernannt. Sie sind einfach gekommen.","road.start.k":"25. Okt. 2026","road.start":"Die Abstimmung","road.end.k":"Block 10.000","road.end":"Fassung 6 beginnt","road.now":"Block {h} · jetzt","road.left":"Noch {n} Blöcke. Beim jetzigen Tempo ist das {eta}.","road.done":"Fassung 6 ist seit Block 10.000 aktiv.","road.need":"Knoten brauchen vor diesem Block eine aktuelle Version.","road.need.done":"Knoten mit einer älteren Version folgen der Kette nicht mehr.","coin.turn":"Umdrehen","coin.turn.back":"Zurückdrehen","coin.back.k":"Block 0","coin.back.d":"9. September 2026","netp.say":"Block {h}, {a} gefunden. {r} arbeiten am nächsten. {n} Knoten sehen zu.","start.jump":"Die fünf Wege","start.guides":"Jeder Weg Schritt für Schritt erklärt","story.road.h":"Die Kette bis heute, und was schon feststeht","story.road.p":"Sieben Marken entlang der Kette. Die hinter uns tragen ihr Datum. Die vor uns tragen nur eine Blocknummer, denn mehr kennt der Code nicht.","story.road.live":"Die neuesten Blöcke ansehen","miles.left":"in {n} Blöcken","forge.hash":"SHA-256, zweimal angewendet","forge.target":"darf das Ziel nicht überschreiten","forge.ok":"Gültig: auf diesem Gerät nachgerechnet.","forge.nodes":"{n} gemeldete Knoten","forge.nodes.1":"1 gemeldeter Knoten","forge.paid":"{r} an {n} Adressen","forge.paid.1":"{r} an eine Adresse","forge.before":"{n} Blöcke davor, im Abstand ihres Fundes: {m} Min.","forge.alt":"Die 136 Byte des neuesten Blockkopfs. Die Nonce wechselt, bis der Hash unter dem Ziel liegt, dann prüfen ihn die Knoten, und der Block nimmt seinen Platz am Ende der Kette ein und zahlt seine Belohnung.","term.note.live":"Von der öffentlichen API beantwortet am {d}.","term.note.snap":"Die Antwort vom {d}. Die API antwortet gerade nicht; die Seite fragt von selbst wieder.","term.more":"Alle {n} Zeilen zeigen","term.less":"Weniger Zeilen zeigen","term.alt":"Eine Anfrage an die öffentliche API und ihre Antwort","agol.sec":"vor {n} Sekunden","agol.sec.1":"vor einer Sekunde","agol.min":"vor {n} Minuten","agol.min.1":"vor einer Minute","agol.hours":"vor {n} Stunden","agol.hours.1":"vor einer Stunde","agol.days":"vor {n} Tagen","agol.days.1":"vor einem Tag","netp.k":"Netz, live","netp.k.snap":"Netz am {date}","netp.say.snap":"Block {h} war der neueste. {r} arbeiteten am nächsten. {n} Knoten sahen zu.","netp.lead.snap":"Der letzte Stand, den diese Seite erhalten hat. Die öffentliche API antwortet gerade nicht; die Seite fragt von selbst wieder.","ex.h1":"Jeder Block ist öffentlich.","ex.lead":"Schlag einen Block, eine Überweisung oder eine Adresse nach. Dein Browser rechnet den Proof of Work jedes angezeigten Blocks selbst nach.","ex.q.ph":"Block, Hash oder Adresse","pulse.tip.h":"Die letzten {n} Stunden","pulse.next":"Block {h} wird gerade geschürft. {t} seit dem letzten Block.","pulse.around.h":"Rund um Block {h}","pulse.around.n":"{n} Blöcke in diesen {k} Stunden","pulse.now":"jetzt","pulse.by":"Gefunden von {who}","pulse.alt":"Blöcke auf einer Zeitachse. Jedes Licht ist ein Block; der Abstand zweier Lichter ist die Zeit zwischen ihnen.","ex.row.tx":"{n} Überweisungen","ex.row.tx.1":"1 Überweisung","ex.row.tx0":"keine Überweisungen","ex.proof.h":"Der Proof of Work","ex.proof.p":"Ein Miner dreht im Blockkopf zwei Zähler, Nonce und Extranonce, bis der Hash aller 136 Byte unter dem Ziel liegt. Dein Browser hat diese Rechnung gerade wiederholt.","proof.pick":"Wähle ein Feld, um zu sehen, was darin steht.","pulse.around.n.1":"Der einzige Block in diesen {k} Stunden","ex.tx.batch":"Sammelzahlung","ex.tx.script":"Ausgabe aus Skript-Konto","ex.txv.status":"Status","ex.txv.waiting":"Wartet auf einen Block","ex.txv.sumPending":"Gesendet, aber noch in keinem Block.","ex.txv.expected":"Voraussichtlich in Block {h}, in etwa {min} Min., sofern nichts mit höherer Gebühr dazukommt.","ex.txv.unknownWhen":"Weiter hinten in der Warteschlange, als die Vorausschau reicht.","ex.addr.waiting":"Wartet","ex.addr.older":"Ältere Bewegungen laden","ex.next.tag":"im Bau","ex.next.h":"Was schon feststeht","ex.next.reward":"Belohnung","ex.next.pending":"Wartende Transaktionen","ex.next.empty":"Der Mempool ist leer, also enthält dieser Block bisher nur die Coinbase.","ex.next.some":"Die wartenden Zahlungen kommen in diesen Block, soweit sie hineinpassen.","ex.next.who":"Wer ihn findet, steht noch nicht fest.","ex.fill":"{p} % voll","ex.fill.of":"{n} von {max} Transaktionen","ex.queue.h":"Warteschlange","ex.queue.row":"{n} Tx · ab {fee} · ~{min} Min.","ex.queue.none":"Nichts wartet — der nächste Block nimmt alles mit.","ex.queue.more":"{n} Transaktionen in insgesamt {b} Blöcken.","ex.queue.note":"Voraussichtliche Reihenfolge nach Gebühr je Byte, unter der Annahme, dass nichts Neues dazukommt. Die Gebühr gilt für eine Überweisung ohne Notiz.","ex.check.h":"Prüfung in deinem Browser","ex.check.note":"Diese Prüfungen laufen hier, nicht auf dem Server.","ex.check.ser":"Serialisierung","ex.check.hash":"Hash nachgerechnet","ex.check.pow":"Proof of Work","ex.check.link":"Verkettung","ex.check.ok":"stimmt","ex.check.bad":"stimmt NICHT","ex.check.open":"offen","ex.check.p":"Header aus den Einzelfeldern neu zusammengesetzt, doppelt gehasht, gegen die eingetragene Difficulty geprüft, Verkettung verfolgt. Diese Prüfungen laufen hier, nicht auf dem Server. Welche Blöcke erscheinen, kommt aus dem Spiegel des Servers; er wird mit dem Full Node verglichen, eine Abweichung steht dann hier. Der grüne Punkt auf einem Block heißt: hier nachgerechnet.","ex.f.achieved":"Erreicht","ex.f.time":"Blockzeit","ex.f.time.s":"Abstand zum Vorgänger","ex.verdict.ok":"{n} Blöcke hier nachgerechnet","ex.verdict.ok.1":"{n} Block hier nachgerechnet","ex.verdict.bad":"Eine Prüfung ist fehlgeschlagen","ex.verified":"hier geprüft","ex.mirror.fork":"Der Spiegel zeigt auf Höhe {h} einen anderen Block als der Full Node. Die Liste unten liegt womöglich auf einem anderen Zweig.","ex.mirror.behind":"Der Spiegel liegt {n} Blöcke hinter dem Full Node. Unten fehlen die neuesten.","ex.mirror.behind.1":"Der Spiegel liegt {n} Block hinter dem Full Node. Unten fehlen die neuesten.","lv.an.apk.akku":"Manche Geräte beenden Apps im Hintergrund trotzdem, um Akku zu sparen. Bleibt das Mining von selbst stehen, stell die Akkunutzung der App auf „Nicht eingeschränkt“ (Einstellungen → Apps → YSKAR Wallet → Akku).","lv.an.apk.dienst":"Seit Version 1.0.9 rechnet ein eigener Dienst der App. Das Mining läuft weiter, wenn du die App verlässt oder der Bildschirm gesperrt ist. Solange gemint wird, zeigt Android eine Benachrichtigung mit deiner Hashrate; über „Mining stoppen“ beendest du es direkt dort.","lv.an.apk.hintergrund":"Mining im Hintergrund","lv.an.apk.inst":"Installieren","lv.an.apk.knopf":"Neueste Version herunterladen","lv.an.apk.m1":"Öffne den Bereich „Mining“ und scroll zu „Steuerung“.","lv.an.apk.m2":"Wähle den Modus: Solo oder Pool. Im Pool-Modus schlägt die App einen offenen Pool vor; über „Wechseln“ siehst du alle Pools mit Minern, Leistung, gefundenen Blöcken und Gebühr. Ein voller Pool lässt sich nicht wählen.","lv.an.apk.m3":"Stell „Worker“ und „Rechenanteil“ ein. Worker sind die CPU-Kerne, die mitrechnen; der Rechenanteil legt fest, wie stark sie ausgelastet werden (25 bis 100 %).","lv.an.apk.m4":"Tippe auf „Mining starten“. Fragt Android nach Benachrichtigungen, erlaube sie: So siehst du, dass gemint wird, und kannst es dort auch stoppen.","lv.an.apk.name":"Auf dem Handy heißt diese App „YSKAR Wallet“. Sie ist eine andere App als die neue YSKAR Wallet ohne Mining; beide lassen sich nebeneinander installieren, und deine 12 Wörter funktionieren in beiden.","lv.an.apk.pruefen":"Download prüfen (optional)","lv.an.apk.pruefenText":"Zu jeder Version gehört eine Datei mit der Endung <code>.sha256</code>. Sie enthält die Prüfsumme der APK. Stimmt die Prüfsumme deines Downloads damit überein, ist die Datei genau die, die wir veröffentlicht haben.","lv.an.apk.s1":"Öffne die Download-Seite auf deinem Telefon und tippe auf die Datei <code>yskar-wallet-….apk</code>.","lv.an.apk.s2":"Android fragt, ob Apps aus dieser Quelle (zum Beispiel deinem Browser) installiert werden dürfen. Tippe auf „Einstellungen“ und erlaube es für diese Quelle.","lv.an.apk.s3":"Geh zurück und tippe auf „Installieren“. Google Play Protect zeigt eventuell eine Warnung; das ist bei Apps außerhalb des Play Store normal.","lv.an.apk.s4":"Öffne die App, erstelle eine Wallet oder übernimm deine bestehende mit deinen 12 Wörtern.","lv.an.apk.start":"Mining starten","lv.an.apk.text":"Die Android-App mint im Hintergrund weiter, auch bei gesperrtem Bildschirm, und zeigt dein Mining als Widget auf dem Startbildschirm. Weil Google Play kein Mining auf dem Gerät erlaubt, gibt es diese Fassung direkt bei uns.","lv.an.apk.tipp":"Unsere Empfehlung: alle Worker, Rechenanteil 25 %, im Pool. Das schont Akku und Temperatur, und im Pool kommen kleinere Beträge regelmäßiger. „Gerät kalibrieren“ ermittelt die beste Worker-Zahl für dein Telefon.","lv.an.apk.titel":"Android-App mit Mining","lv.an.apk.update":"App aktualisieren","lv.an.apk.updateText":"Gibt es eine neue Version, zeigt die App beim Öffnen einen Hinweis. Tippe auf „Laden“: Die App lädt das Update, danach fragt Android, ob es installiert werden soll. Deine Wallet bleibt erhalten. Von Hand prüfst du in der App unter Einstellungen → App → Updates.","lv.an.apk.w1":"Halte eine freie Stelle auf dem Startbildschirm gedrückt, wähle „Widgets“ und zieh „YSKAR Wallet“ auf den Bildschirm.","lv.an.apk.w2":"Läuft das Mining, zeigt das Widget, was du in dieser Sitzung verdient hast, dazu Hashrate, Laufzeit und angenommene Shares. Mit „Stopp“ beendest du das Mining direkt vom Startbildschirm. Ist das Mining gestoppt, siehst du den aktuellen Block, die Netz-Hashrate und die Blockbelohnung.","lv.an.apk.w3":"„Verdient in dieser Sitzung“ zählt die Blockbelohnungen und Pool-Anteile, die deiner Adresse seit dem Start gutgeschrieben wurden; der Wert ändert sich, wenn ein neuer Block gefunden wird. Hell oder dunkel wählst du in der App unter Einstellungen → App → Widget. Das Widget in dieser Form gibt es ab Version 1.1.0.","lv.an.apk.widget":"Widget auf dem Startbildschirm","lv.an.etikett":"Anleitungen","lv.an.ex.p1":"Suche nach Blockhöhe, Hash oder Adresse.","lv.an.ex.p2":"Bei jedem Block siehst du, wer ihn gefunden hat: ein Name, ein Pool oder eine Solo-Adresse.","lv.an.ex.p3":"Gib deine eigene Adresse ein, um deine Auszahlungen nachzuprüfen.","lv.an.ex.text":"Der <a href=\"/explorer\">Explorer</a> zeigt jeden Block, jede Überweisung und jede Adresse. Er setzt jeden Block-Header in deinem Browser neu zusammen, hasht ihn und prüft Proof of Work und Verkettung. Überweisungen, Signaturen und Guthaben prüfen Fullnodes – betreibst du einen, musst du niemandem glauben.","lv.an.ex.titel":"Der Explorer","lv.an.gr.aus":"So zahlt ein Pool aus","lv.an.gr.aus1":"Der Block selbst zahlt alle Beteiligten direkt aus. Der Betreiber des Pools hält nie dein Geld, und es gibt keine Auszahlungsschwelle.","lv.an.gr.aus2":"Gezählt wird die Arbeit der letzten Zeit, gemessen in Shares. Wer gerade erst angefangen hat, bekommt beim ersten Block entsprechend wenig.","lv.an.gr.gebuehr":"Der Betreiber kann eine Gebühr zwischen 0 und 5 % nehmen. Sie steht in der Pool-Liste.","lv.an.gr.hinweis":"Niemand kann dir einen Ertrag zusagen. Wie oft du etwas erhältst, hängt von deiner Rechenleistung, von der Leistung des Netzes und vom Zufall ab.","lv.an.gr.p1":"YSKAR ist eine eigene Blockchain. Etwa alle 10 Minuten wird ein neuer Block gefunden. Wer ihn findet, erhält die Belohnung – derzeit 875 YSR – direkt auf seine Adresse.","lv.an.gr.p2":"Um einen Block zu finden, probiert dein Gerät Zahlen durch (doppeltes SHA-256). Je mehr Rechenleistung du hast, desto größer deine Chance. Die Schwierigkeit passt sich an die Leistung des ganzen Netzes an.","lv.an.gr.plaetze":"Ein Block kann höchstens 64 Adressen auszahlen, deshalb hat ein Pool höchstens 64 Plätze (63, wenn er eine Gebühr nimmt). Ein Platz zählt nur, solange du minest: Ein neues Gerät hält ihn 2 Minuten auf Probe und behält ihn, indem es regelmäßig Shares abgibt. Plätze von Minern, die aufhören, werden wieder frei.","lv.an.gr.pool":"<strong>Pool:</strong> Viele suchen gemeinsam. Findet der Pool einen Block, wird die Belohnung nach geleisteter Arbeit aufgeteilt. Kleinere Beträge, dafür regelmäßiger.","lv.an.gr.solo":"<strong>Solo:</strong> Du suchst allein. Findest du einen Block, gehört dir die ganze Belohnung. Das kann lange dauern.","lv.an.gr.sp":"Solo oder Pool","lv.an.gr.titel":"So funktioniert das Mining","lv.an.hi.a1":"Android schließt die App, um Akku zu sparen. Stell die Akkunutzung der YSKAR Wallet auf „Nicht eingeschränkt“ (Einstellungen → Apps → YSKAR Wallet → Akku).","lv.an.hi.a2":"Ein Pool hat höchstens 64 Plätze. Ein Platz wird sofort frei, wenn ein Miner aufhört, und bis zu 20 Minuten nachdem ein Miner verstummt – ein späterer Versuch kann also klappen. Sonst wähle einen anderen Pool oder mine solo. Hat deine Adresse schon einen Platz, können weitere Geräte trotzdem mitmachen.","lv.an.hi.a3":"Der Knoten hat noch keinen anderen Knoten gefunden. Prüfe deine Internetverbindung und ob du Node Core bei der Nachfrage der Windows-Firewall erlaubt hast. Warte dann einen Moment.","lv.an.hi.a4":"Der Knoten synchronisiert noch. Das Mining startet, sobald die Übersicht „Synchron“ zeigt.","lv.an.hi.a5":"Mining mit der GPU braucht eine Grafikkarte von NVIDIA, AMD oder Intel mit aktuellem Treiber. Installiere den aktuellen Treiber des Herstellers und starte Node Core neu. Vor dem Mining prüft sich jede Karte selbst; eine Karte, die den Test nicht besteht, wird nicht genutzt.","lv.an.hi.a6":"Stell die Wallet mit denselben 12 Wörtern in derselben Reihenfolge wieder her. Andere Wörter sind eine andere Wallet.","lv.an.hi.a7":"Fragen stellst du im <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">Community-Chat auf Telegram</a>. Fehler meldest du auf <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. Gib nie deine 12 Wörter weiter: Admins schreiben dich nie zuerst an.","lv.an.hi.f1":"Das Mining auf dem Telefon stoppt von selbst","lv.an.hi.f2":"„Pool voll“","lv.an.hi.f3":"Node Core: „Noch kein Peer verbunden“","lv.an.hi.f4":"Node Core: Das Mining startet nicht","lv.an.hi.f5":"Die GPU wird nicht gefunden","lv.an.hi.f6":"Auf einem neuen Gerät fehlt mein Guthaben","lv.an.hi.f7":"Etwas anderes","lv.an.hi.titel":"Wenn etwas nicht klappt","lv.an.mini.hinweis":"Tipp: Im Bereich „Mining“ kannst du zwischen Solo und Pool wählen. Im Pool bekommst du öfter kleinere Beträge, solo seltener, dafür ganze Blöcke.","lv.an.mini.s1":"Öffne <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> in Telegram und starte die App.","lv.an.mini.s2":"Tippe auf „Wallet erstellen“. Die App zeigt dir 12 Wörter: Schreib sie in der richtigen Reihenfolge auf Papier.","lv.an.mini.s3":"Bestätige einige der Wörter und lege eine PIN fest.","lv.an.mini.s4":"Öffne den Bereich „Mining“ und tippe auf „Mining starten“. Lass die App offen, solange sie rechnet.","lv.an.mini.text":"Der schnellste Einstieg. Die Mini App läuft direkt in Telegram; es gibt nichts zu installieren.","lv.an.mini.titel":"Telegram Mini App","lv.an.nc.e1":"<strong>Knoten:</strong> Datenordner, Ports und Seed sind vorausgefüllt. Die Standardwerte passen für die meisten – klick einfach auf „Weiter“.","lv.an.nc.e2":"<strong>Wallet:</strong> Lege eine neue Wallet an und schreib die 12 Wörter auf, oder übernimm deine bestehende Wallet mit deinen 12 Wörtern. Wähle ein Passwort mit mindestens 8 Zeichen; es verschlüsselt die Wörter auf diesem PC. Du kannst die Wallet auch später einrichten.","lv.an.nc.e3":"<strong>Start:</strong> Klick auf „Knoten starten“.","lv.an.nc.einst":"Einstellungen","lv.an.nc.erst":"Erster Start","lv.an.nc.firewall":"Beim ersten Start fragt Windows, ob Node Core ins Netzwerk darf. Erlaube es, sonst findet der Knoten keine anderen Knoten.","lv.an.nc.firewallLinux":"Unter Linux gibt es diese Abfrage nicht. Ist eine Firewall aktiv (etwa ufw), gib Port 8646 frei – sonst erreichen andere Knoten deinen nicht. Deine eigenen Verbindungen klappen so oder so.","lv.an.nc.i1":"Lade den Installer herunter und starte ihn.","lv.an.nc.i2":"Windows zeigt „Der Computer wurde durch Windows geschützt“, weil der Installer nicht signiert ist. Wähle „Weitere Informationen“, dann „Trotzdem ausführen“.","lv.an.nc.i3":"Folge dem Installer. Danach startet Node Core.","lv.an.nc.inst":"Installieren unter Windows","lv.an.nc.l1":"<strong>Ubuntu, Debian, Linux Mint:</strong> Lade die <code>.deb</code>-Datei herunter und installiere sie im Terminal. Danach startest du „YSKAR Node Core“ aus dem Anwendungsmenü.","lv.an.nc.l2":"<strong>Andere Distributionen:</strong> Lade das AppImage herunter, mach es ausführbar und starte es. AppImages brauchen FUSE 2 (unter Ubuntu das Paket <code>libfuse2</code>).","lv.an.nc.l3":"Node Core für Linux läuft auf 64-Bit-PCs (x86-64) mit Desktop. ARM-Rechner wie der Raspberry Pi werden nicht unterstützt.","lv.an.nc.linux":"Installieren unter Linux","lv.an.nc.m1":"Wähle das Ziel: Solo oder Pool. Im Pool nimmst du einen Pool aus der Liste oder trägst unter „Eigene Pool-Adresse“ eine Adresse ein und prüfst sie.","lv.an.nc.m2":"„Belohnung geht an“: deine eigene Wallet oder eine andere Adresse.","lv.an.nc.m3":"Wähle das Gerät: CPU, GPU oder beides. Stell die Zahl der CPU-Kerne und die Auslastung je Kern ein.","lv.an.nc.m4":"Nur solo: Trag auf Wunsch einen Namen ein, der in deinen gefundenen Blöcken steht. Er ist öffentlich und bleibt dauerhaft.","lv.an.nc.m5":"Klick auf „Mining starten“.","lv.an.nc.mining":"Mining","lv.an.nc.poolHinweis":"Nimmt dich ein Pool nicht mehr auf, stoppt das Mining und nennt den Grund. Es rechnet nie stillschweigend solo weiter.","lv.an.nc.port":"Muss ich einen Port freigeben?","lv.an.nc.portText":"Nein. Ohne Freigabe verbindet sich dein Knoten selbst mit anderen Knoten. Gibst du Port 8646 im Router frei, können andere Knoten auch deinen erreichen. Das hilft dem Netz, ist aber freiwillig.","lv.an.nc.pruefen":"Wenn du sichergehen willst, dass die Datei die veröffentlichte ist, vergleiche ihre Prüfsumme mit der Datei <code>.sha256</code> der Veröffentlichung. In PowerShell:","lv.an.nc.pruefenLinux":"Unter Linux:","lv.an.nc.s1":"<strong>Mit Windows starten</strong> (unter Linux: „Beim Anmelden starten“): Node Core startet beim Anmelden ohne Fenster.","lv.an.nc.s2":"<strong>Beim Schließen weiterlaufen:</strong> Das Fenster verschwindet in den Infobereich neben der Uhr, der Knoten arbeitet weiter.","lv.an.nc.s3":"<strong>Mining nach dem Start fortsetzen:</strong> Das Mining läuft mit den letzten Einstellungen weiter, sobald der Knoten synchron ist.","lv.an.nc.s4":"<strong>Updates:</strong> Node Core weist dich auf eine neue Version hin. Installiert wird nichts von selbst.","lv.an.nc.sig":"Signieren und YSKAR Lab","lv.an.nc.sigText":"Seit Version 1.1.0 signiert „Signieren“ in der Wallet einen Text mit deiner Adresse, zum Beispiel um zu beweisen, dass dir eine Adresse gehört; „Prüfen“ prüft die signierte Nachricht eines anderen. Auf <a href=\"https://lab.yskar.app\">lab.yskar.app</a> öffnet „Mit Wallet anmelden“ Node Core: Es zeigt die Website, deine Adresse und wie lange die Anfrage gilt, und signiert erst, wenn du mit deinem Passwort bestätigst. Eine Signatur kann keine YSR bewegen.","lv.an.nc.sync":"Die erste Synchronisation","lv.an.nc.syncText":"Beim ersten Start lädt Node Core die ganze Blockchain und prüft jeden Block. Das kann eine Weile dauern; den Fortschritt zeigt die Übersicht. Das Mining startet erst, wenn der Knoten auf dem Stand des Netzes ist.","lv.an.nc.text":"Node Core ist das YSKAR-Programm für Windows und Linux: dein eigener Knoten mit Wallet und Mining in einem Fenster. Es lädt die Blockchain auf deinen PC und prüft jeden Block selbst.","lv.an.nc.titel":"Node Core für Windows und Linux","lv.an.nc.update":"Aktualisieren","lv.an.nc.updateText":"Lade den neuen Installer herunter, beende Node Core – auch im Infobereich – und starte den Installer. Deine Wallet und die Blockchain bleiben erhalten.","lv.an.nc.v1":"Windows 10 oder 11 (64 Bit) oder Linux (64 Bit, x86-64) und eine Internetverbindung","lv.an.nc.v2":"Speicherplatz für die Blockchain. Sie ist noch klein und wächst mit jedem Block.","lv.an.nc.v3":"Für Mining mit der Grafikkarte (GPU): eine GPU von NVIDIA, AMD oder Intel mit aktuellem Treiber. Ohne sie rechnet der Prozessor (CPU).","lv.an.nc.vor":"Das brauchst du","lv.an.nc.w1":"<strong>Senden:</strong> Empfänger und Betrag eingeben, prüfen, mit dem Passwort bestätigen. Das Passwort wird vor jeder Überweisung verlangt.","lv.an.nc.w2":"<strong>Empfangen:</strong> Zeig deine Adresse oder ihren QR-Code.","lv.an.nc.w3":"<strong>Kontakte:</strong> Namen statt Adressen, gespeichert nur auf diesem PC.","lv.an.nc.w4":"<strong>Sperre:</strong> Die Wallet sperrt sich nach 10 Minuten ohne Eingabe und immer, wenn Windows gesperrt wird. Die Zeit stellst du in den Einstellungen ein.","lv.an.nc.wallet":"Wallet","lv.an.node.s1":"1. Bauen","lv.an.node.s2":"2. Starten und mit dem Netz verbinden","lv.an.node.s2Text":"Der Knoten verbindet sich mit einem anderen Knoten (dem Seed), lädt die Kette und prüft sie Block für Block. Andere Knoten erreichen deinen über Port 8646, wenn du ihn im Router freigibst; das ist optional. Mit --no-upstream gibt dein Knoten Blöcke nur an andere Knoten weiter, nicht an den Webserver des Projekts.","lv.an.node.s3":"3. Gegen den eigenen Knoten minen","lv.an.node.s4":"4. Einen Pool betreiben (optional)","lv.an.node.s4Fuss":"--pool-fee ist in Basispunkten: 100 = 1,00 %, höchstens 500.","lv.an.node.s4Mehr":"Was ein Pool braucht, damit App und andere Miner ihn erreichen, steht unter <a href=\"/anleitungen#pool\">Einen Pool betreiben</a>.","lv.an.node.s4Text":"Jeder Knoten kann ein Pool sein, ohne Anmeldung. Der Block selbst zahlt alle Beteiligten aus; du hältst nie fremdes Guthaben.","lv.an.node.s5":"5. Als Dienst auf dem Raspberry Pi","lv.an.node.s5Text":"Damit der Knoten nach einem Neustart von selbst startet, richte ihn als systemd-Dienst ein. Fertige Dateien und eine Anleitung liegen im Repository unter <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a>.","lv.an.node.text":"Ein Fullnode lädt die Kette und prüft jeden Block selbst – Proof of Work, Signaturen, Guthaben. Er braucht Node.js ab Version 22.13 und läuft gut auf einem Raspberry Pi.","lv.an.node.titel":"Einen Fullnode betreiben","lv.an.node.win":"Unter Windows npm.cmd statt npm verwenden.","lv.an.pc.s1":"1. Node.js installieren","lv.an.pc.s1Text":"Der Miner braucht Node.js ab Version 20. Lade die LTS-Fassung von <a href=\"https://nodejs.org\">nodejs.org</a> und installiere sie. Unter Windows danach ein neues Eingabefenster öffnen.","lv.an.pc.s2":"2. Miner holen","lv.an.pc.s2Text":"Mehr ist nicht zu installieren. Der Selbsttest prüft, ob dein Rechner die Hashes richtig berechnet.","lv.an.pc.s3":"3. Mining starten","lv.an.pc.s3Text":"Ersetze die Adresse durch deine eigene YSKAR-Adresse (sie beginnt mit ysr1). Mit dem Pool:","lv.an.pc.s4":"4. Grafikkarte (GPU, optional)","lv.an.pc.s4Text":"Mit einer Grafikkarte ergänzt du <code>--gpu</code>. Dafür braucht es ein GPU-Programm: <code>yskar-cuda</code> für NVIDIA-Karten, <code>yskar-opencl</code> für Karten von AMD und Intel. Der Miner nimmt das erste, das eine Karte findet; mit <code>--gpu-api opencl</code> nutzt er das Programm für AMD und Intel auch dann, wenn eine NVIDIA-Karte steckt. Für Linux hängen beide an jeder Veröffentlichung von Node Core (<code>yskar-cuda-…-linux-x86_64</code>, <code>yskar-opencl-…-linux-x86_64</code>); unter Windows baust du sie wie im Repository unter <code>node-core/gpu</code> beschrieben.","lv.an.pc.s5":"5. Mining-Rigs mit HiveOS","lv.an.pc.s5Text":"Für Mining-Rigs mit HiveOS gibt es ein fertiges Paket: dieser Miner mit dem GPU-Programm, ein Miner je Grafikkarte von NVIDIA, AMD oder Intel, ohne Gebühr. Es hängt an jeder Veröffentlichung von Node Core als <code>yskar-hiveos-….tar.gz</code>. Wie das Flight Sheet eingerichtet wird, steht in <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>.","lv.an.pc.solo":"Solo statt Pool: --mode pool weglassen. Ganze Blöcke, dafür seltener.","lv.an.pc.text":"Der Miner läuft unter Windows, macOS und Linux. Er braucht nur eine Adresse – keinen privaten Schlüssel, keine Wallet, keine Anmeldung. Du kannst ihn bedenkenlos auf jedem Rechner laufen lassen.","lv.an.pc.titel":"PC-Miner","lv.an.pool.beitritt":"So treten Miner bei","lv.an.pool.beitrittText":"In der App wählst du „Pool“ und trägst die Adresse deines Pools unter „Eigene Adresse“ ein, im Node Core unter „Eigene Pool-Adresse“. Mit dem PC-Miner:","lv.an.pool.caddy":"Die Konfiguration für Caddy. Ersetze den Namen durch deinen; er muss vorher auf deinen Rechner zeigen.","lv.an.pool.g1":"<strong>Name:</strong> 3 bis 32 einfache Zeichen. Er steht in jedem Block deines Pools und bleibt dort für immer.","lv.an.pool.g2":"<strong>Gebühr:</strong> 0 bis 5 %. Im Befehl steht <code>--pool-fee</code> in Basispunkten: 100 = 1 %. Mit Gebühr musst du die Adresse nennen, an die sie geht.","lv.an.pool.g3":"<strong>Plätze:</strong> höchstens 64 Adressen, mit Gebühr 63 – ein Empfänger bist du.","lv.an.pool.g4":"<strong>Kein fremdes Geld:</strong> Der Block zahlt alle direkt aus. Du hältst nie Guthaben deiner Miner.","lv.an.pool.h1":"Öffne „Pool betreiben“, leg Namen, Gebühr und Zahl der Plätze fest und schalte ein.","lv.an.pool.h2":"Wähle im Mining „Pool“. Dein eigener Pool steht dort zuerst.","lv.an.pool.h3":"Für weitere PCs schaltest du „Geräte im Heimnetz“ ein. Sie verbinden sich mit <code>http://&lt;Adresse dieses PCs&gt;:8645</code>.","lv.an.pool.heim":"Im Heimnetz mit Node Core","lv.an.pool.heimText":"Der Pool im Node Core antwortet nur dem eigenen PC und dem eigenen Netz. Aus dem Internet ist er so nicht erreichbar.","lv.an.pool.k1":"Wer mitmint","lv.an.pool.k2":"Was du brauchst","lv.an.pool.liste":"In die Pool-Liste kommen","lv.an.pool.listeText":"App und Node Core zeigen eine gepflegte Liste von Pools. Für einen Eintrag muss dein Pool über HTTPS erreichbar sein und <code>/api/v2/pool</code> beantworten. Frag dafür auf <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a> an. Die Liste ist keine Prüfung und keine Empfehlung: Miner, Leistung und Gebühr meldet ein Pool selbst.","lv.an.pool.n1":"<strong>Einen Knoten, der dauernd läuft.</strong> Am besten der Kommandozeilen-Knoten auf einem Raspberry Pi oder Server – siehe <a href=\"/anleitungen#fullnode\">Einen Fullnode betreiben</a>.","lv.an.pool.n2":"<strong>Einen Namen</strong>, unter dem er erreichbar ist: eine eigene Domain oder ein kostenloser DynDNS-Name.","lv.an.pool.n3":"<strong>HTTPS mit gültigem Zertifikat.</strong> Telegram und Browser laden nichts Unverschlüsseltes nach. Ohne HTTPS erreicht kein Telefon deinen Pool.","lv.an.pool.n4":"<strong>Einen Webserver davor</strong>, der das Zertifikat holt und Anfragen an den Knoten weiterreicht, zum Beispiel Caddy.","lv.an.pool.n5":"<strong>Port 443 offen.</strong> Bei einem Knoten zu Hause heißt das: eine Portfreigabe im Router.","lv.an.pool.netz":"Für App, Mini App und Miner aus dem Internet","lv.an.pool.netzText":"Das brauchst du:","lv.an.pool.o1":"<strong>Zu Hause:</strong> keine Zusatzkosten. Aber deine IP-Adresse wird öffentlich bekannt, du brauchst eine Portfreigabe, und dein Anschluss trägt die Last.","lv.an.pool.o2":"<strong>Gemieteter Server:</strong> Deine IP-Adresse zu Hause bleibt außen vor, und auf dem Server liegen keine Schlüssel – nur die Adresse für die Gebühr. Lies vorher die Bedingungen des Anbieters: Viele verbieten Mining oder alles, was damit zu tun hat. Lass dir den Einsatz schriftlich bestätigen.","lv.an.pool.ort":"Zu Hause oder auf einem gemieteten Server?","lv.an.pool.r1a":"Du und Geräte in deinem Heimnetz","lv.an.pool.r1b":"Node Core mit eingeschaltetem „Pool betreiben“","lv.an.pool.r2a":"PC-Miner aus dem Internet","lv.an.pool.r2b":"Einen Knoten, der dauernd läuft und von außen erreichbar ist","lv.an.pool.r3a":"App und Mini App","lv.an.pool.r3b":"Zusätzlich HTTPS: einen Namen (Domain oder DynDNS) und ein Zertifikat","lv.an.pool.regeln":"Regeln für jeden Pool","lv.an.pool.start":"Starte den Knoten als Pool. Er lauscht nur auf dem Rechner selbst; davor steht der Webserver.","lv.an.pool.test":"Prüfe von außen. Enthält die Antwort deinen Pool-Namen und die Zahl der Plätze, ist der Pool erreichbar.","lv.an.pool.text":"Ein Pool ist bei YSKAR kein Dienst mit Konten. Er ist ein Knoten, der die Belohnung seiner Blöcke aufteilt. Jeder kann einen betreiben, ohne Anmeldung. Was du brauchst, hängt davon ab, wer bei dir mitminen soll.","lv.an.pool.titel":"Einen Pool betreiben","lv.an.si.p1":"<strong>Deine 12 Wörter sind deine Wallet.</strong> Gib sie nie auf einer Webseite ein und schick sie niemandem. Niemand von YSKAR wird danach fragen.","lv.an.si.p2":"<strong>Lade nur von yskar.app und vom YSKAR-Projekt auf GitHub.</strong> Wenn du sichergehen willst, vergleiche die Prüfsumme.","lv.an.si.p3":"<strong>Halte deine Programme aktuell.</strong> Bei einer angekündigten Regeländerung bleibt ein veralteter Knoten entweder an diesem Block stehen oder läuft weiter, ohne die neue Regel zu prüfen – beides ist ein Grund, rechtzeitig zu aktualisieren.","lv.an.si.p4":"<strong>Wenn du einen Knoten betreibst:</strong> Andere Knoten sehen deine IP-Adresse, wie in jedem Peer-to-Peer-Netz. Eine Portfreigabe brauchst du nicht. Wer seine Adresse nicht zeigen will, nutzt ein VPN.","lv.an.si.p5":"<strong>Node Core:</strong> Wallet und Oberfläche sind nur von deinem eigenen PC aus erreichbar.","lv.an.si.titel":"Sicherheit","lv.an.text":"Alles Schritt für Schritt erklärt: Mining auf dem Telefon und am PC, deine Wallet, dein eigener Knoten und dein eigener Pool.","lv.an.titel":"Schritt für Schritt","lv.an.tocLabel":"Auf dieser Seite","lv.an.ue.k1":"Weg","lv.an.ue.k2":"Geeignet für","lv.an.ue.k3":"Du brauchst","lv.an.ue.r1a":"Telegram Mini App","lv.an.ue.r1b":"Ausprobieren, sofort","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"Android-App","lv.an.ue.r2b":"Mining im Hintergrund auf dem Telefon","lv.an.ue.r2c":"Ein Android-Telefon","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"Eigener Knoten mit Wallet und Mining am PC, mit CPU und GPU","lv.an.ue.r3c":"Windows 10/11 oder Linux (64 Bit)","lv.an.ue.r4a":"PC-Miner","lv.an.ue.r4b":"Mining über die Kommandozeile","lv.an.ue.r4c":"Windows, macOS oder Linux mit Node.js","lv.an.ue.r5a":"Full Node","lv.an.ue.r5b":"Knoten oder Pool auf einem Raspberry Pi oder Server","lv.an.ue.r5c":"Linux, Windows oder macOS mit Node.js 22.13 oder neuer","lv.an.ue.text":"Es gibt fünf Wege mitzumachen. Alle nutzen dieselbe Wallet: Mit deinen 12 Wörtern kommst du überall an dasselbe Guthaben.","lv.an.ue.titel":"Welcher Weg passt zu dir?","lv.an.w.empfangen":"Empfangen","lv.an.w.empfangenText":"Zeig deine Adresse oder ihren QR-Code. Du kannst dem Code einen Betrag und eine Notiz mitgeben; der Absender muss dann nur noch bestätigen. Deine Adresse darfst du jedem geben – deine 12 Wörter niemandem.","lv.an.w.kontakte":"Kontakte und Verlauf","lv.an.w.kontakteText":"Kontakte geben Adressen einen Namen; sie liegen nur auf deinem Gerät. Der Verlauf zeigt jede Zahlung; die Mining-Erträge eines Tages stehen gebündelt in einer Zeile und lassen sich bis zum einzelnen Block aufklappen.","lv.an.w.s1":"Empfänger: Adresse einfügen, QR-Code scannen oder einen Kontakt wählen. Eine YSKAR-Adresse beginnt mit ysr1.","lv.an.w.s2":"Betrag und auf Wunsch eine Notiz mit bis zu 32 Byte – das sind 32 einfache lateinische Buchstaben, mit Umlauten oder anderen Schriften weniger. Die Notiz steht öffentlich in der Blockchain.","lv.an.w.s3":"Gebühr: Die App schlägt sie vor. Ohne Andrang genügt die Mindestgebühr für den nächsten Block.","lv.an.w.s4":"Prüfen: Die App zeigt die volle Adresse und sagt dir, ob du schon einmal dorthin gesendet hast. Bestätige mit PIN oder Fingerabdruck.","lv.an.w.senden":"Senden","lv.an.w.warn":"Eine gesendete Zahlung lässt sich nicht zurückholen. Prüfe die ganze Adresse, bevor du bestätigst.","lv.an.wallet.p1":"Schreib die Wörter in der richtigen Reihenfolge auf Papier. Kein Screenshot, keine Cloud.","lv.an.wallet.p2":"Bewahre das Papier sicher auf. Wenn dein Telefon verloren geht, stellen die Wörter alles wieder her.","lv.an.wallet.p3":"Die PIN schützt nur die App auf diesem Gerät. Sie ersetzt die Wörter nicht.","lv.an.wallet.p4":"Für ein neues Gerät wählst du „Ich habe schon zwölf Wörter“ und gibst sie ein.","lv.an.wallet.text":"Deine Wallet entsteht auf deinem Gerät aus 12 Wörtern. Diese Wörter sind dein Schlüssel: Wer sie hat, kommt an das Guthaben – auf jedem Gerät, in jeder YSKAR-App.","lv.an.wallet.titel":"Deine Wallet","lv.fuss.datenschutz":"Datenschutz","lv.fuss.impressum":"Impressum","lv.hood.f2.k":"Difficulty","lv.nc.appimage":"AppImage für andere Linux-Distributionen","lv.nc.bildNotiz":"Beispielansicht – die Zahlen sind Beispiele.","lv.nc.knopfLinux":"Für Linux herunterladen (.deb)","lv.nc.knopfWin":"Für Windows herunterladen","lv.nc.mehr":"Prüfsumme und Hinweise zur Version","lv.nc.system":"Windows 10 oder 11 (64 Bit)","lv.nc.systemLinux":"Linux 64 Bit · Ubuntu, Debian, Mint","lv.pr.block.alt":"Der 136-Byte-Blockkopf und seine zehn Felder","lv.pr.block.merkle":"Ein Hash über alle Transaktionen des Blocks. Ändert sich ein einziges Byte einer Überweisung, ändert er sich mit.","lv.pr.block.nonce":"Die Zahl, die Miner verändern. Die ersten 128 Byte bleiben je Auftrag gleich, daher kostet jeder Versuch nur zwei SHA-256-Kompressionsschritte.","lv.pr.block.prev":"Der Hash des vorherigen Blocks. Er verkettet die Blöcke: Wer einen alten Block ändert, ändert jeden Hash danach.","lv.pr.block.state":"Ein Hash über alle Konten (Guthaben und Nonce) nach diesem Block. Jeder Knoten berechnet ihn selbst und vergleicht.","lv.pr.block.text":"Jeder Block beginnt mit genau 136 Byte. Sein Hash ist doppeltes SHA-256 über diese Bytes und darf das Ziel, das die Difficulty vorgibt, nicht überschreiten.","lv.pr.block.titel":"Aufbau eines Blockkopfs","lv.pr.db.ablauf":"Ablauf","lv.pr.db.ablaufWert":"optional, per Blockhöhe","lv.pr.db.adresse":"Adresse","lv.pr.db.adresseWert":"ysr1…, 42 Zeichen; gemeinsame Konten ab V6: ysr1p…, 63 Zeichen (bech32m)","lv.pr.db.blockzeitWert":"600 Sekunden (Ziel)","lv.pr.db.diffWert":"LWMA über 45 Blöcke, nach jedem Block","lv.pr.db.einheit":"Kleinste Einheit","lv.pr.db.gebuehr":"Gebühren gehen an","lv.pr.db.gebuehrWert":"den Miner des Blocks","lv.pr.db.kette":"Die Kette","lv.pr.db.knoten":"Full Nodes","lv.pr.db.knotenWert":"jeder hält und prüft die ganze Kette","lv.pr.db.konsens":"Konsens","lv.pr.db.konsensWert":"Proof of Work, SHA-256d","lv.pr.db.memo":"Notiz (Memo)","lv.pr.db.memoWert":"bis zu 32 Byte","lv.pr.db.minGeb":"Mindestgebühr (Konsens)","lv.pr.db.minGebWert":"1 Einheit je Byte","lv.pr.db.modell":"Modell","lv.pr.db.modellWert":"Konten mit Guthaben und Nonce","lv.pr.db.muenze":"Der Coin","lv.pr.db.name":"Name · Kürzel","lv.pr.db.netz":"Netz","lv.pr.db.notfall":"Notfallregel","lv.pr.db.notfallWert":"leichter nach 30 Min. ohne Block","lv.pr.db.nullkonto":"Verbrennadresse","lv.pr.db.pfad":"Schlüsselableitung","lv.pr.db.pool":"Pools","lv.pr.db.poolWert":"Auszahlung aus dem Block, Gebühr 0–5 %","lv.pr.db.relay":"Mindestgebühr zum Weiterleiten","lv.pr.db.relayWert":"10 Einheiten je Byte","lv.pr.db.sig":"Signaturen","lv.pr.db.staub":"Kleinster sendbarer Betrag","lv.pr.db.staubWert":"100 Einheiten","lv.pr.db.transfer":"Größe einer Überweisung","lv.pr.db.transferWert":"168 bis 200 Byte","lv.pr.db.tx":"Transaktionen je Block","lv.pr.db.txWert":"bis zu 2.000","lv.pr.db.vorab":"Pre-Mine · Zuteilung","lv.pr.db.vorabWert":"keine","lv.pr.db.wahl":"Kettenwahl","lv.pr.db.wahlWert":"meiste angesammelte Arbeit","lv.pr.db.wallet":"Wallets und Konten","lv.pr.db.worte":"Seed-Wörter","lv.pr.db.worteWert":"BIP39, 12 oder 24 Wörter","lv.pr.etikett":"Das Protokoll im Detail","lv.pr.gen.belohnung":"Belohnung","lv.pr.gen.belohnungWert":"875 YSR, nicht ausgebbar","lv.pr.gen.text":"Der erste Block der Kette. Seine Coinbase enthält eine kurze Botschaft, und seine Belohnung ging an eine Adresse, von der niemand etwas ausgeben kann.","lv.pr.gen.titel":"Block 0","lv.pr.gen.zeit":"Zeitstempel","lv.pr.pruefen":"Prüf Block 0 oder den neuesten Block selbst, direkt in deinem Browser.","lv.pr.text":"Alles hier ist im Konsenscode festgelegt und für jeden Knoten gleich. Nichts davon hängt an einem Server, einem Unternehmen oder einer Einstellung.","lv.pr.titel1":"YSKAR und YSR,","lv.pr.titel2":"Byte für Byte.","lv.pr.tx.alt":"Felder einer Überweisung","lv.pr.tx.p1":"Die Signatur umfasst auch die Chain-ID. Eine für YSKAR signierte Überweisung ist in jedem anderen Netz ungültig.","lv.pr.tx.p2":"Die Nonce zählt die gesendeten Überweisungen eines Kontos. Dieselbe Überweisung kann nie zweimal ausgeführt werden.","lv.pr.tx.p3":"Eine optionale Ablaufhöhe lässt eine Überweisung verfallen, wenn sie bis dahin nicht aufgenommen wurde.","lv.pr.tx.text":"Eine Überweisung bewegt YSR von einem Konto zu einem anderen. Sie ist 168 Byte groß, plus eine optionale Notiz.","lv.pr.tx.titel":"Aufbau einer Überweisung","lv.recht.nurDeutsch":"Diese Seite ist nach deutschem Recht auf Deutsch.","lv.supply.aera.fuss":"Belohnungen zählen in ganzen Basiseinheiten (0,00000001 YSR), bei jeder Halbierung fällt der Rest weg: Insgesamt werden 20.999.999,99832 YSR ausgegeben, knapp unter dem Maximum.","lv.supply.aera.k1":"Ära","lv.supply.aera.k2":"Blöcke","lv.supply.aera.k3":"Belohnung je Block","lv.supply.aera.k4":"In der Ära ausgegeben","lv.supply.aera.k5":"Gesamt nach der Ära","lv.supply.aera.text":"Eine Ära dauert 12.000 Blöcke, etwa 83 Tage. In jeder Ära ist die Belohnung halb so groß wie in der vorigen. Ab Block 444.000 entstehen keine neuen YSR mehr, Miner erhalten dann nur noch die Gebühren.","lv.supply.aera.titel":"Ausgabe nach Ära","lv.wallet.warnung":"<strong>Wer die 12 Wörter hat, hat das Guthaben.</strong> Gib sie niemals weiter. Niemand von YSKAR wird dich jemals danach fragen.","lv.wpseite.drucken":"Drucken / als PDF speichern","lv.wpseite.toc":"Inhalt","lv.wpseite.untertitel":"Eine Proof-of-Work-Blockchain, die jeder minen und jeder nachprüfen kann.","lv.zahlen.blockzeit":"Blockzeit","lv.wpseite.nurDeEn":"Das Whitepaper gibt es derzeit auf Deutsch und Englisch.","unit.min":"{n} Min.","unit.hours":"{n} Stunden","unit.days":"{n} Tagen","ago.sec":"vor {n} s","ago.min":"vor {n} Min.","ago.hours":"vor {n} Std.","ago.days":"vor {n} Tagen","eta.around":"in etwa {d}, um den {date}","v6.active":"Aktiv seit Block 10.000","v6.pending":"noch {n} Blöcke","mode.live":"Live aus der Kette","mode.snapshot":"Stand vom {date}","mode.history":"Verlauf bis Block {h}","mode.liveShort":"Live","mode.snapshotShort":"Letzter Stand","dur.years":"{n} Jahre","dur.years.big":"{n} Jahre","dur.days":"{n} Tage","dur.hours":"{n} Stunden","dur.min":"{n} Minuten","dur.sec":"{n} Sekunden","dur.sec.1":"1 Sekunde","rm.run.p":"Veröffentlicht und in Gebrauch. Jeder Eintrag führt dorthin, wo du ihn prüfen kannst.","rm.run.1.h":"Hauptnetz","rm.run.1.p":"Blöcke seit dem 9. Sep. 2026. Die Kette steht bei Block","rm.run.1.l":"Das Netz, live","rm.run.2.h":"Konsensfassungen 2 bis 5","rm.run.2.p":"Aktiv seit den Blöcken 2.000, 4.000, 6.000 und 7.000.","rm.run.2.l":"Was jede geändert hat","rm.run.3.p":"Full Node, Wallet, CPU- und GPU-Mining und Poolbetrieb für Windows und Linux.","rm.run.3.l":"Herunterladen","rm.run.4.p":"Die Android-Wallet: senden, empfangen, signieren. Bereit für Fassung 6.","rm.run.4.l":"Zur Wallet","rm.run.5.h":"Drei öffentliche Pools","rm.run.5.p":"YSKAR MAIN, Gozero und ODW.Serv. Die Pool-Software ist offen; jeder kann einen betreiben.","rm.run.5.l":"Die Pools, live","rm.run.6.h":"Explorer und öffentliche API","rm.run.6.p":"Jeder Block, jede Überweisung und jede Adresse, im Browser und über HTTP.","rm.run.6.l":"Explorer öffnen","rm.run.7.p":"Vorschläge, Diskussion und Status, alles offen. Du meldest dich mit deiner Wallet an.","rm.fix.p":"Diese Änderungen stehen im Konsens-Code. Sie gelten ab einem Block und nicht ab einem Datum: Wann dieser Block kommt, hängt davon ab, wie schnell Blöcke gefunden werden.","rm.fix.blocks":"Blöcke","rm.fix.1.at":"Block 10.000","rm.fix.1.h":"Fassung 6","rm.fix.1.p":"Gemeinsame Konten mit bis zu 16 Schlüsseln, Zeitsperren und Hash-Sperren, Sammelüberweisungen an bis zu 1.000 Empfänger und Platz für 5.000 Transaktionen je Block. Ein Hard Fork, festgelegt nach einer Community-Abstimmung am 25. Okt. 2026. Knoten müssen vor diesem Block eine aktuelle Version betreiben.","rm.fix.1.l":"Was sich bei Block 10.000 ändert","rm.fix.2.at":"Block 12.000","rm.fix.2.h":"Erste Halbierung","rm.fix.2.p":"Die Blockbelohnung fällt von 875 auf 437,5 YSR. Sie halbiert sich danach alle 12.000 Blöcke erneut.","rm.fix.2.l":"Der ganze Plan","rm.fix.after":"Die letzten neuen YSR entstehen in Block 443.999. Danach verdienen Miner nur noch Gebühren.","rm.plan.p":"Beabsichtigt, nicht versprochen. Nichts hiervon hat einen Termin, und die Reihenfolge kann sich ändern.","rm.plan.1.h":"Swaps und Echtzeit-Zahlungen","rm.plan.1.p":"Fassung 6 bringt die Bausteine in die Kette: Hash-Sperren und Zeitsperren. Wallet-Funktionen, die sie für Swaps und für Zahlungen in Echtzeit nutzen, kommen danach.","rm.plan.2.h":"Stratum für Mining-Rigs","rm.plan.2.p":"Heute sprechen Miner und Pools YSKARs eigenes HTTP-Protokoll. Stratum ist geplant, sobald das Netz gewachsen ist.","rm.plan.3.h":"Mining auf gemeinsame Konten","rm.plan.3.p":"Fassung 6 kann eine Blockbelohnung nicht an ein gemeinsames Konto auszahlen. Die Spezifikation überlässt das Fassung 7.","rm.plan.4.h":"Die Wallet am eigenen Knoten","rm.plan.4.p":"Heute liest YSKAR Wallet Guthaben vom öffentlichen Server. Geplant: sie auf einen Full Node richten, den du selbst betreibst.","rm.plan.5.h":"YSKAR Wallet im Play Store","rm.plan.5.p":"Heute ist die Wallet eine APK aus den GitHub-Releases.","rm.plan.6.h":"Öffentliches Testnetz und Mitbestimmung","rm.plan.6.p":"Die nächsten Stufen von YSKAR Lab: Änderungen ausprobieren, bevor sie das Hauptnetz erreichen, und gemeinsam darüber entscheiden.","rm.plan.7.h":"Börsenlistings","rm.plan.7.p":"In Vorbereitung, ohne Datum und ohne Namen. Heute hat YSR keinen Preis und keinen Markt, und niemand sollte in der Erwartung minen, dass sich das ändert.","rm.how.p":"Vorschläge werden im YSKAR Lab öffentlich geschrieben, besprochen und verfolgt. Eine Änderung der Konsensregeln braucht eine Spezifikation, und sie erreicht das Hauptnetz nur zu einer Blockhöhe, die jeder Knoten im Voraus kennt.","com.ch.p":"Ankündigungen erscheinen zuerst im Telegram-Kanal. Alles andere ist für Fragen und Diskussion da.","com.ch.1":"Releases und Neuigkeiten.","com.ch.2":"Fragen und Diskussion mit anderen Minern und Nutzern.","com.ch.3":"Kurze Meldungen von @yskar_official.","com.ch.4":"Der Ankündigungs-Thread.","com.ch.5":"Quelltext, Releases und Issues.","com.ch.6":"Vorschläge, von der ersten Idee bis zum Release.","com.do.1.h":"Einen Full Node betreiben","com.do.1.p":"Jeder Knoten, der die Blöcke selbst prüft, macht das Netz unabhängiger von jedem einzelnen Server.","com.do.2.h":"Minen, allein oder im Pool","com.do.2.p":"Rechenleistung, die sich auf viele Miner und mehrere Pools verteilt, macht die Kette schwerer zu lenken.","com.do.3.h":"Einen Pool betreiben","com.do.3.p":"Die Pool-Software ist Teil des Repositorys und zahlt Miner im Block selbst aus. Ein weiterer unabhängiger Pool verteilt die Rechenleistung weiter.","com.do.4.h":"Testen und melden","com.do.4.p":"Probiere ein Release aus und eröffne ein Issue für das, was nicht funktioniert. Schreib, was du gesehen hast und wie es sich nachstellen lässt.","com.do.5.h":"Vorschlagen und diskutieren","com.do.5.p":"Bring eine Idee ins YSKAR Lab oder verbessere die eines anderen in den Kommentaren.","com.lab.p":"Jeder Vorschlag durchläuft dieselben sechs Stufen, und jeder sieht, wo er steht.","com.lab.s1":"Idee","com.lab.s1.d":"Teile, was dir vorschwebt.","com.lab.s2":"Diskussion","com.lab.s2.d":"Gemeinsam in den Kommentaren verbessern.","com.lab.s3":"Entwurf","com.lab.s3.d":"Text, Design, Spezifikation oder Code.","com.lab.s4":"Geplant","com.lab.s4.d":"Für ein kommendes Release vorgesehen, mit Begründung.","com.lab.s5":"Im Testnetz","com.lab.s5.d":"Ausprobieren, bevor es das Hauptnetz erreicht.","com.lab.s6":"Veröffentlicht","com.lab.s6.d":"Erschienen, mit Link dorthin.","com.lab.k1":"Durch die ersten drei Stufen bewegt der Autor seinen Vorschlag selbst.","com.lab.k2":"Ab Geplant setzt das Team die Stufe, immer mit Begründung.","com.lab.open":"YSKAR Lab öffnen","com.safe.1.h":"Deine 12 Wörter bleiben bei dir","com.safe.1.p":"Niemand von YSKAR wird je nach deinen 12 Wörtern, deiner PIN oder einer Wallet-Datei fragen. Wer danach fragt, will an deine Coins.","com.safe.2.h":"Lade von der Quelle","com.safe.2.p":"Hol dir die Software aus den GitHub-Releases, auf die diese Seite verweist, und vergleiche vor der Installation den Zertifikats-Fingerabdruck der Wallet.","com.safe.3.h":"Keine Versprechen","com.safe.3.p":"YSR hat heute keinen Preis und keinen Markt und ist an keiner Börse gelistet. Nichts hier verspricht, dass sich das ändert.","com.channel":"Telegram-Kanal","com.chat":"Community-Chat","wallet.dl":"APK herunterladen","wallet.meta":"Version 2.0.0, für Android 7 oder neuer. Open Source unter der MIT-Lizenz. Englisch und Deutsch.","wallet.feat.p":"Keine Werbung, kein Tracking und kein Konto bei irgendwem. Die App spricht mit dem YSKAR-Netz und mit sonst nichts.","wallet.f1.h":"Dein Schlüssel bleibt bei dir","wallet.f1.p":"Die Wallet entsteht auf deinem Handy. 12 Wörter stellen sie auf jedem Gerät wieder her. Sie liegen mit deiner PIN verschlüsselt im geschützten Speicher von Android und landen nie in Cloud-Backups.","wallet.f2.h":"Senden mit Absicht","wallet.f2.p":"Adresse eingeben, Kontakt wählen oder QR-Code scannen. Vor dem Senden siehst du Empfänger, Betrag und Netzgebühr noch einmal, dann schiebst du zum Bestätigen. Eine Überweisung lässt sich nicht zurückholen.","wallet.f3.h":"Empfangen und anfordern","wallet.f3.p":"Zeig deinen QR-Code oder deine Adresse. Auf Wunsch forderst du einen bestimmten Betrag an: Der Absender muss dann nur noch bestätigen.","wallet.f5.h":"Signieren und anmelden","wallet.f5.p":"Mit einer signierten Nachricht belegen, dass eine Adresse dir gehört, und die Signaturen anderer prüfen. Per QR-Code im YSKAR Lab anmelden. Eine Signatur kann keine YSR bewegen.","wallet.f6.h":"Abgesichert","wallet.f6.p":"PIN und Fingerabdruck, automatische Sperre nach einer Zeit deiner Wahl, keine Screenshots, solange die 12 Wörter zu sehen sind, und eine eigene Tastatur, damit keine Eingabe durch die Tastatur-App deines Handys läuft.","wallet.inst.h":"In vier Schritten installieren","wallet.inst.p":"Die Wallet wird als APK über ihre GitHub-Releases verteilt. Updates installieren sich über die vorige Version, deine Wallet bleibt auf dem Gerät.","wallet.inst.1":"Öffne das <a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>neueste Release</a> auf deinem Android-Handy und lade die Datei <code>yskar-wallet-…apk</code>.","wallet.inst.2":"Öffne die Datei. Erlaube die Installation aus dieser Quelle, wenn Android fragt.","wallet.inst.3":"Tippe auf „Wallet erstellen“ und schreibe die 12 Wörter auf Papier, in der richtigen Reihenfolge.","wallet.inst.4":"Wähle eine PIN. Um eine bestehende Wallet herüberzuholen, gib stattdessen ihre 12 Wörter ein.","wallet.verify.h":"Prüfen, ob die Datei echt ist","wallet.verify.p":"Jedes Release ist mit demselben Schlüssel signiert. Das ist der SHA-256-Fingerabdruck seines Zertifikats. Weicht der Fingerabdruck deines Downloads ab, installiere die Datei nicht.","wallet.oth.h":"Andere Orte für deine YSR","wallet.oth.p":"Jede YSKAR-App nutzt dieselben 12 Wörter. Damit erreichst du überall dasselbe Guthaben.","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android. Senden, empfangen, signieren. Sie mint nicht.","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows und Linux. Eine Wallet im eigenen Full Node, mit Mining und Nachrichten-Signatur. <a href='/mining#setup'>Node Core holen</a>","wallet.oth.3.h":"Android-App mit Mining","wallet.oth.3.p":"Wallet und Mining auf dem Handy, mit Widget und Benachrichtigungen.","wallet.oth.4.h":"Telegram Mini App","wallet.oth.4.p":"Der einfache Einstieg, ohne Installation. Der Besitz hängt an deinen 12 Wörtern, nicht an deinem Telegram-Konto.","wallet.st.h":"Wo die Wallet steht","wallet.st.1.h":"Nur Android","wallet.st.1.p":"Die Wallet ist eine APK von GitHub. Sie ist in keinem App-Store, und eine iOS-App gibt es nicht.","wallet.st.2.h":"Bereit für Fassung 6","wallet.st.2.p":"Version 2.0.0 kennt das neue Überweisungsformat und schaltet bei Block 10.000 darauf um. Eine ältere Version empfängt weiter YSR, kann nach diesem Block aber nicht mehr senden.","wallet.st.3.h":"Geplant: ein App-Store","wallet.st.3.p":"Eine Veröffentlichung über Google Play ist geplant. Einen Termin gibt es nicht.","wallet.st.4.h":"Geplant: der eigene Knoten","wallet.st.4.p":"Heute liest die Wallet vom Hauptknoten des Projekts. Geplant ist, sie mit einem selbst betriebenen Knoten zu verbinden, damit niemand dem Projekt ein Guthaben glauben muss.","mining.ways.p":"Jeder Weg ist kostenlos und nutzt dieselbe Wallet: Mit deinen 12 Wörtern erreichst du überall dieselben YSR.","mining.tab.pc":"PC","mining.tab.phone":"Handy","mining.tab.cli":"Kommandozeile","mining.tab.rig":"Rig","mining.pc.h":"Node Core für Windows und Linux","mining.pc.p":"Full Node, Wallet und Miner in einem Programm. Node Core prüft jeden Block selbst und mint mit deinem Prozessor und mit Grafikkarten von NVIDIA, AMD und Intel. Version 1.1.0, für Windows 10 und 11 sowie 64-Bit-Linux.","mining.pc.s1":"Installer herunterladen und ausführen.","mining.pc.s2":"Wallet erstellen und die 12 Wörter notieren, oder deine Wallet damit herüberholen.","mining.pc.s3":"Unter Mining solo oder einen Pool wählen, Prozessor oder Grafikkarte auswählen und starten.","mining.pc.win":"Für Windows herunterladen","mining.pc.deb":"Für Linux herunterladen (.deb)","mining.pc.more":"Außerdem: ein <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a> für andere Linux-Distributionen und die <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>Release-Notizen mit Prüfsummen</a>.","mining.pc.note":"<strong>Der Windows-Installer ist nicht signiert.</strong> Windows fragt deshalb einmal nach: „Weitere Informationen“ wählen, dann „Trotzdem ausführen“. Wer sichergehen will, vergleicht die Prüfsumme mit den Release-Notizen.","mining.pc.imgcap":"Node Core, Übersicht. Die Zahlen im Bild sind Beispiele.","mining.phone.h":"Auf dem Handy","mining.phone.p":"Der einfachste Weg, YSKAR kennenzulernen. Ein Handy bringt wenig Rechenleistung mit und findet Blöcke nur im Pool. Ernsthaftes Mining läuft auf PCs und Rigs.","mining.phone.s1":"Android-App von GitHub installieren oder die Mini App in Telegram öffnen.","mining.phone.s2":"Wallet erstellen und die 12 Wörter auf Papier notieren.","mining.phone.s3":"Einen Pool wählen und das Mining starten.","mining.phone.apk":"Android-App mit Mining","mining.phone.tg":"Mini App in Telegram","mining.phone.f1":"Android-App","mining.phone.f1.v":"Mint im Hintergrund weiter, auch bei gesperrtem Bildschirm, und zeigt den Stand in einem Widget. Wird als APK verteilt, weil App-Stores Mining auf dem Gerät nicht zulassen.","mining.phone.f2":"Mini App","mining.phone.f2.v":"Nichts zu installieren. Läuft in Telegram, solange es geöffnet ist. Deine Coins hängen an deinen 12 Wörtern, nicht an deinem Telegram-Konto.","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"Die Wallet-App mint nicht. Sie ist zum Senden, Empfangen und Signieren da.","mining.cli.h":"Der Kommandozeilen-Miner","mining.cli.p":"Für Windows, macOS und Linux. Der Miner braucht nur eine Adresse: keinen Schlüssel, keine Wallet und keine Anmeldung. Er lässt sich auch auf einem Rechner betreiben, den du nicht kontrollierst.","mining.cli.f1":"Voraussetzung","mining.cli.f1.v":"Node.js 20 oder neuer, sonst nichts zu installieren","mining.cli.f2":"Grafikkarten","mining.cli.f2.v":"<code>--gpu</code> anhängen. Genutzt wird <code>yskar-cuda</code> für NVIDIA und <code>yskar-opencl</code> für AMD und Intel","mining.cli.f3":"Solo","mining.cli.f3.v":"gegen den eigenen Full Node minen und <code>--mode pool</code> weglassen","mining.cli.link":"Die vollständige Anleitung zum Miner","mining.cli.c1":"Miner holen und diesen Rechner testen","mining.cli.c2":"im öffentlichen Pool minen","mining.cli.c3":"oder solo, gegen den eigenen Knoten","mining.cli.addr":"Ersetze <code>ysr1...</code> durch deine eigene Adresse. Belohnungen gehen direkt dorthin.","mining.rig.h":"Mining-Rigs mit HiveOS","mining.rig.p":"Ein fertiges Paket für HiveOS: der Kommandozeilen-Miner mit den GPU-Programmen, ein Miner je Grafikkarte.","mining.rig.dl":"Paket 1.1.0 herunterladen","mining.rig.doc":"Flight Sheet und Einrichtung","mining.rig.f1":"Karten","mining.rig.f1.v":"NVIDIA (CUDA), AMD und Intel (OpenCL)","mining.rig.f2":"Gebühr","mining.rig.f2.v":"keine im Miner. Ein Pool behält seine eigene Gebühr","mining.rig.f3":"Einrichtung","mining.rig.f3.v":"deine Adresse und der Pool stehen im Flight Sheet. Die Anleitung zeigt jedes Feld","mining.return":"<strong>Niemand kann dir einen Ertrag versprechen.</strong> Wie oft du etwas erhältst, hängt von deiner Rechenleistung ab, von der des ganzen Netzes und vom Zufall. YSR hat keinen Marktpreis.","pools.p1":"Solo suchst du allein und behältst die ganze Belohnung eines Blocks, den du findest. Im Pool suchen viele gemeinsam, und die Belohnung wird nach der Arbeit aufgeteilt, die jeder geliefert hat.","pools.p2":"Ein YSKAR-Pool ist kein Dienst mit Konten. Er ist ein Knoten, dessen Blöcke jeden Miner direkt auszahlen, im Block selbst. Der Betreiber hält nie fremde Coins, und es gibt keine Auszahlungsschwelle.","pools.reported":"{r} gemeldet","pools.c5":"Von den letzten {n}","pools.full":"voll","pools.cap":"Miner, Plätze und Hashrate meldet jeder Pool selbst. Der Anteil an den letzten {n} Blöcken ist aus der Kette gezählt.","pools.f1":"Abrechnung","pools.f1.v":"Nach den Shares der jüngsten Vergangenheit (PPLNS). Wer gerade erst angefangen hat, bekommt vom ersten Block einen kleinen Teil.","pools.f2":"Plätze","pools.f2.v":"Ein Block kann höchstens 64 Adressen auszahlen, ein Pool hat also 63 Plätze plus die Gebühr des Betreibers. Ab Fassung 6 sind es 254.","pools.f3":"Gebühr","pools.f3.v":"Legt der Betreiber fest, zwischen 0 und 5 %.","pools.f4":"Ein eigener Pool","pools.f4.v":"Jeder Knoten kann ein Pool sein, ohne Anmeldung. <a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>So betreibst du einen</a>","calc.p":"Gib deine Hashrate ein. Die Schätzung nutzt die Arbeit in den neuesten Blöcken der Kette, nicht die Werte, die Pools über sich selbst melden. Node Core und der Miner zeigen deine Hashrate im Betrieb an.","calc.unit":"Einheit","calc.mode":"Wie du minst","calc.pool":"Im Pool","calc.solo":"Solo","calc.which":"Pool","calc.day":"Pro Tag, im Mittel","calc.week":"In 7 Tagen","calc.month":"In 30 Tagen","calc.share":"Dein Anteil am Netz","calc.d.every":"Ein Block im Mittel alle","calc.d.chance":"Chance auf mindestens einen Block in 24 Stunden","calc.d.block":"Je gefundenem Block","calc.d.poolEvery":"Der Pool findet einen Block etwa alle","calc.d.part":"Dein Teil jedes Pool-Blocks","calc.d.fee":"Pool-Gebühr, schon abgezogen","calc.d.poolShare":"Anteil des Pools an den letzten {n} Blöcken","calc.d.net":"Netz-Hashrate aus den letzten {n} Blöcken","calc.enter":"Gib eine Hashrate über 0 ein.","calc.note":"Eine Schätzung, kein Versprechen. Blöcke werden zufällig gefunden, und die Difficulty folgt dem ganzen Netz. Gebühren sind nicht eingerechnet.","calc.halving":"Die Halbierung bei Block {b} kommt in etwa {d} Tagen. Die Werte für 7 und 30 Tage rechnen danach schon mit der halben Belohnung.","calc.halving.1":"Die Halbierung bei Block {b} kommt in etwa einem Tag. Die Werte für 7 und 30 Tage rechnen danach schon mit der halben Belohnung.","calc.every.min":"{n} Minuten","calc.every.min.1":"1 Minute","calc.every.hours":"{n} Stunden","calc.every.days":"{n} Tage","calc.every.years":"{n} Jahre","net.hashrate":"Netz-Hashrate","net.difficulty":"Difficulty","net.now":"Im Moment","net.height":"Blockhöhe","net.fromChain":"Arbeit der letzten 24 Blöcke, geteilt durch ihre Zeit","net.everyBlock":"für jeden Block neu berechnet","net.blocktime":"Blockzeit, letzte 50 Blöcke","net.target600":"Ziel: 600 s","net.mempool":"Wartende Überweisungen","net.fromNode":"beim Hauptknoten","net.miners":"Aktive Miner","net.sessions":"Mining-Sitzungen","net.nodes":"Meldende Knoten","net.reported":"gemeldet, nicht prüfbar","net.next.v6":"Fassung 6 bei Block 10.000","net.next.halving":"Erste Halbierung bei Block 12.000","net.hist.h":"Verlauf, aus den Blöcken gelesen","net.hist.p":"Jeder Block der Kette, je Tag in UTC zusammengefasst. Der Verlauf ist vollständig bis Block <span data-live='snapTip'></span>; die Werte oben werden live gelesen.","net.range":"Zeitraum","net.range.all":"Seit Block 0","net.range.30":"30 Tage","net.range.7":"7 Tage","net.c.hash":"Hashrate je Tag","net.c.hash.capLog":"Arbeit der Blöcke eines Tages, geteilt durch ihre Zeit. Logarithmische Skala: Jede Linie ist das Zehnfache der darunter.","net.c.hash.capLin":"Arbeit der Blöcke eines Tages, geteilt durch ihre Zeit.","net.c.blocks":"Blöcke je Tag","net.c.blocks.cap":"Nur vollständige Tage. Bei der Zielblockzeit hat ein Tag 144 Blöcke.","net.c.blocks.ref":"Ziel: 144 Blöcke je Tag","net.c.blocks.name":"Blöcke","net.c.finders":"Blöcke je Tag, nach Finder","net.c.finders.cap":"Nur vollständige Tage. Pool-Blöcke tragen den Namen des Pools in der Kette; ein Block, der eine einzige Adresse auszahlt, zählt als solo.","net.c.time":"Mittlere Blockzeit je Tag","net.c.time.cap":"Sekunden zwischen den Blöcken, über den Tag gemittelt.","net.c.time.ref":"Ziel: 600 Sekunden","net.c.day":"Tag (UTC)","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"Wer die Blöcke findet","net.find.p1":"In den ersten Wochen wurde jeder Block solo gefunden. Heute kommen fast alle Blöcke aus zwei Pools, und die meisten aus einem.","net.find.p2":"Das ist wichtig. Der Betreiber eines Pools wählt die Transaktionen und den Vorgänger jedes Blocks, an dem der Pool arbeitet, und wer den Großteil der Rechenleistung lenkt, kann die Kette mit der meisten Arbeit bauen. Mehr Pools und mehr Solo-Miner machen die Kette schwerer zu lenken.","net.find.link":"Die Pools, und wie du einen eigenen betreibst","net.find.title":"Anteil der gefundenen Blöcke","net.find.last":"Letzte {n} Blöcke","net.find.last1000":"Die 1.000 Blöcke bis Block {h}","net.find.allb":"Alle Blöcke bis Block {h}","net.find.cap":"Aus der Kette gezählt. Der erste Balken folgt der Live-Kette, die beiden anderen enden dort, wo der eingebettete Verlauf endet.","net.blocks.h":"Die neuesten Blöcke","net.blocks.p":"Wähle einen Block, um seinen Kopf zu sehen, seinen Proof of Work nachzurechnen und seine Transaktionen zu lesen.","net.blocks.link":"Explorer öffnen","net.blocks.title":"Neueste zuerst","net.b.height":"Höhe","net.b.age":"Gefunden","net.b.by":"Von","net.b.paid":"Ausgezahlt an","net.b.diff":"Difficulty","net.b.solo":"solo","net.b.addr":"{n} Adressen","net.b.addr.1":"1 Adresse","net.src.h":"Woher die Zahlen kommen","net.src.p":"Nicht jede Zahl auf dieser Seite hat dasselbe Gewicht.","net.src.1.h":"Aus der Kette","net.src.1.p":"Höhe, Difficulty, Menge und jedes Diagramm auf dieser Seite. Die Hashrate ist die Arbeit der neuesten Blöcke, geteilt durch die Zeit, die sie gebraucht haben. Wer einen Full Node betreibt, kann alles davon nachrechnen.","net.src.2.h":"Gemeldet","net.src.2.p":"Aktive Miner, Sitzungen, Knoten und die Hashrate, die ein Pool über sich angibt. Das sind Selbstauskünfte. Sie zeigen eine Richtung, und niemand kann sie prüfen.","net.src.3.h":"Der Spiegel","net.src.3.p":"Diese Seite und der Explorer lesen eine Datenbankkopie der Kette, damit sie schnell laden. Der Spiegel prüft jeden Block, den er speichert, bleibt aber ein Komfort. Die Kette ist das, worauf sich die Full Nodes einigen.","net.src.4.h":"Seed-Knoten","net.src.4.p":"Ein neuer Knoten kontaktiert zuerst <code>pool.yskar.app:8646</code> oder <code>yskar-seed2.dynv6.net:8646</code>. Beide betreibt derselbe Betreiber. Danach tauschen die Knoten die Adressen anderer Knoten untereinander aus.","ex.q.label":"Die Kette durchsuchen","ex.q.go":"Suchen","ex.try":"Zum Einstieg:","ex.try.0":"Block 0","ex.try.burn":"die Vernichtung in Block 3.974","ex.try.or":"oder","ex.try.zero":"die Adresse, von der niemand ausgeben kann","ex.crumb":"Explorer","ex.msg.empty":"Gib eine Blockhöhe, einen Blockhash, eine Transaktions-ID oder eine Adresse ein.","ex.msg.badAddr":"Diese Adresse enthält einen Tippfehler: Ihre Prüfsumme stimmt nicht. Prüfe sie Zeichen für Zeichen.","ex.msg.addrShape":"Das ist keine YSKAR-Adresse. Adressen beginnen mit ysr1 und haben 42 Zeichen.","ex.msg.tooHigh":"Block {h} gibt es noch nicht. Die Kette steht bei Block {tip}.","ex.msg.notFound":"Dazu gibt es nichts in der Kette.","ex.msg.offlineHash":"Die Kette antwortet gerade nicht, deshalb lässt sich dieser Hash nicht nachschlagen. Versuch es gleich noch einmal.","ex.msg.searching":"Die Kette wird durchsucht.","ex.msg.badLink":"Dieser Link führt zu keinem Block, keiner Transaktion und keiner Adresse.","ex.loading":"Wird aus der Kette gelesen.","ex.missing.h":"Die Kette antwortet gerade nicht","ex.missing.p":"Der Explorer liest jeden Block, jede Überweisung und jede Adresse aus der öffentlichen YSKAR-API, und diese Anfrage ist gerade fehlgeschlagen. Er versucht es von selbst wieder, sobald die Kette antwortet.","ex.missing.link":"Jetzt erneut versuchen","ex.none.block":"Die Kette hat keinen Block {h}. Sie steht bei Block {tip}.","ex.none.tx":"Zu dieser ID ist keine Transaktion bekannt: Sie steht in keinem Block und wartet auch auf keinen. Hast du sie eben erst gesendet, sieht diese Seite von selbst wieder nach.","ex.back":"Zurück zu den neuesten Blöcken","ex.latest.h":"Neueste Blöcke","ex.latest.snap":"Die Kette antwortet gerade nicht. Das sind die neuesten {n} Blöcke zum Zeitpunkt der letzten Antwort.","ex.latest.live":"Aus der öffentlichen API gelesen und alle 45 Sekunden erneuert.","ex.older":"Ältere Blöcke zeigen","ex.older.busy":"Wird gelesen","ex.c.height":"Höhe","ex.c.found":"Gefunden","ex.c.by":"Von","ex.c.transfers":"Überweisungen","ex.c.size":"Größe","ex.c.hash":"Blockhash","ex.solo":"Solo-Miner","ex.bytes":"{n} Byte","ex.block.h":"Block {h}","ex.prev":"Vorheriger Block","ex.next":"Nächster Block","ex.block.sumPool":"Gefunden am {date}, {ago}, vom Pool {who}.","ex.block.sumSolo":"Gefunden am {date}, {ago}, von einem Solo-Miner.","ex.block.sumGenesis":"Der erste Block der Kette, datiert auf den {date}. Seine Belohnung ging an eine Adresse, von der niemand ausgeben kann.","ex.block.partial":"Die Kette antwortet gerade nicht. Das ist der Kopf des Blocks, wie die Seite ihn schon hatte; seinen Proof of Work kannst du also trotzdem prüfen. Seine Transaktionen folgen, sobald die Kette antwortet.","ex.block.values":"Was im Kopf steht","ex.block.values.p":"Diese Werte stecken in den 136 Byte oben. Ändert sich einer davon, passt der Hash nicht mehr.","ex.f.hash":"Blockhash","ex.f.prev":"Vorheriger Block","ex.f.prev.none":"Keiner. Das ist der erste Block.","ex.f.merkle":"Merkle-Wurzel","ex.f.merkle.s":"Fingerabdruck der Transaktionen in diesem Block","ex.f.state":"Zustandswurzel","ex.f.state.s":"Fingerabdruck aller Guthaben nach diesem Block","ex.f.diff":"Difficulty","ex.f.diff.s":"Im Mittel waren etwa {n} Versuche nötig","ex.f.nonce":"Nonce und Extranonce","ex.f.nonce.s":"Die beiden Zähler, die der Miner gedreht hat, bis der Hash passte","ex.f.size":"Größe","ex.f.size.v":"{n} Byte mit {tx} Transaktionen","ex.f.size.v.1":"{n} Byte mit 1 Transaktion","ex.txs.h":"Transaktionen in diesem Block","ex.txs.p":"Die erste erzeugt die Blockbelohnung. Jede weitere ist eine Überweisung, die ihr Absender unterschrieben hat.","ex.tx.coinbase":"Blockbelohnung","ex.tx.transfer":"Überweisung","ex.tx.other":"Transaktion vom Typ {type}","ex.tx.new":"{a} neu erzeugt","ex.tx.newFees":"{a} neu erzeugt und {f} aus Gebühren","ex.tx.from":"Von","ex.tx.to":"An","ex.tx.amount":"Betrag","ex.tx.fee":"Gebühr","ex.tx.memo":"Notiz","ex.tx.memoHex":"Notiz (Bytes)","ex.tx.nonce":"Zähler des Absenders","ex.tx.nonce.s":"Jede Überweisung einer Adresse trägt die nächste Nummer, so lässt sich keine wiederholen","ex.tx.id":"Transaktions-ID","ex.tx.paid":"Im Block selbst an {n} Adressen ausgezahlt. Der Pool hat diese Coins nie gehalten.","ex.tx.c.addr":"Adresse","ex.tx.c.amount":"Betrag in YSR","ex.tx.c.share":"Anteil","ex.unspendable":"nicht ausgebbar","ex.txv.sum":"Bestätigt in Block {h} am {date}.","ex.txv.block":"Block","ex.txv.until":"Gültig bis","ex.txv.until.none":"Kein Ablauf gesetzt","ex.txv.until.h":"Block {h}","ex.txv.size":"Größe","ex.txv.raw":"Die Bytes, wie sie im Block stehen","ex.txv.raw.p":"Ein Knoten prüft genau diese Bytes: die Unterschrift, das Guthaben des Absenders und den Zähler.","ex.txv.how":"Wie eine Überweisung aufgebaut ist","ex.addr.h":"Adresse","ex.addr.zero":"Für diese Adresse hält niemand einen Schlüssel. Was hier ankommt, kann nie wieder ausgegeben werden.","ex.addr.balance":"Guthaben","ex.addr.sent":"Gesendete Überweisungen","ex.addr.first":"Zuerst gesehen","ex.addr.last":"Zuletzt aktiv","ex.addr.blockN":"Block {h}","ex.addr.solo":"Erhaltene Blockbelohnungen","ex.addr.pool":"Erhaltene Pool-Auszahlungen","ex.addr.hist":"Letzte Aktivität","ex.addr.more":"Die neuesten {n} Einträge.","ex.addr.none":"Die Kette hat zu dieser Adresse noch keinen Eintrag. Eine Adresse ist gültig, sobald ihr Schlüssel existiert; die Kette erfährt von ihr mit der ersten Zahlung.","ex.h.block":"Block","ex.h.when":"Wann","ex.h.what":"Was","ex.h.with":"Mit","ex.h.amount":"Betrag","ex.h.fee":"Gebühr","ex.k.in":"Empfangen","ex.k.out":"Gesendet","ex.k.reward":"Blockbelohnung","ex.k.pool":"Pool-Auszahlung","ex.copy.addr":"Adresse kopieren","ex.copy.id":"ID kopieren","ex.block.sumPoolNoName":"Gefunden am {date}, {ago}, von einem Pool.","dev.node.h":"Einen Full Node betreiben","dev.node.p":"Ein Full Node führt seine eigene Kopie der Kette und prüft jeden Block selbst. Er glaubt nichts ungeprüft, weder anderen Knoten noch dieser Website.","dev.node.link":"Was ein Knoten in jedem Block prüft","dev.node.c1":"Quelltext holen und den Knoten bauen","dev.node.c2":"Starten: mit den Seed-Knoten verbinden, Kette laden, jeden Block prüfen","dev.node.c3":"Gegen den eigenen Knoten minen, in einem zweiten Terminal","dev.node.f1.k":"Du brauchst","dev.node.f1.v":"Node.js 22.13 oder neuer und Git. Der Knoten speichert die Kette mit dem SQLite-Modul, das in Node.js eingebaut ist.","dev.node.f2.k":"Ports","dev.node.f2.v":"TCP 8646 für andere Knoten, 8645 für die HTTP-Schnittstelle, die Miner und Wallets nutzen.","dev.node.f3.k":"Uhr","dev.node.f3.v":"Halte die Systemuhr richtig. Ein Block, der mehr als 120 Sekunden vor der Uhr deines Knotens liegt, wird abgelehnt.","dev.node.f4.k":"Seed-Knoten","dev.node.f4.v":"Der Kommandozeilen-Knoten hat keinen Seed eingebaut. Nenne beide Seed-Knoten, wie im Befehl oben.","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"Gehört in den Befehl. Ohne die Option würde der Knoten auch Blöcke mit dem Datenbankspiegel des Projekts austauschen, der nur Blöcke vom Hauptknoten annimmt.","dev.node.core":"Unter Windows tippst du in der PowerShell <code>npm.cmd</code> statt <code>npm</code>. Wer ein Fenster dem Terminal vorzieht: <a href=\"/node#core\">Node Core</a> betreibt denselben Full Node unter Windows und Linux.","dev.api.h":"Die Kette über HTTP lesen","dev.api.p":"Die öffentliche API beantwortet einfache GET-Anfragen mit JSON. Wähle eine Anfrage und lies die Antwort.","dev.api.title":"API-Konsole","dev.api.pick":"Anfragen","dev.api.out":"Antwort","dev.api.run":"Erneut senden","dev.api.curl":"Als curl kopieren","dev.api.busy":"Warte auf die Antwort.","dev.api.ok":"{status} nach {ms} ms, live beantwortet von www.yskar.app.","dev.api.fail":"Die Anfrage ist fehlgeschlagen ({why}). Gezeigt wird die letzte Antwort, die diese Seite erhalten hat, vom {date}.","dev.api.e.summary":"Höhe, Difficulty, Hashrate, Menge","dev.api.e.blocks":"Die neuesten Blöcke, neueste zuerst","dev.api.e.block":"Ein Block mit allen Transaktionen","dev.api.e.tx":"Eine Transaktion über ihre ID","dev.api.e.account":"Guthaben und Verlauf einer Adresse","dev.api.e.search":"Was für ein Ding ist dieser Text?","dev.api.e.fees":"Die Gebühr, die eine Überweisung gerade braucht","dev.api.e.pools":"Die Pools und ihre gemeldeten Zahlen","dev.api.e.supply":"Geschürft, nicht ausgebbar und im Umlauf","dev.api.e.circ":"Die umlaufende Menge als reine Zahl","dev.api.n1.h":"Nur lesend und offen","dev.api.n1.p":"Kein Schlüssel und kein Konto. Anfragen von anderen Websites sind erlaubt, eine Webseite kann die API also direkt aufrufen.","dev.api.n2.h":"Dein eigener Knoten antwortet auch","dev.api.n2.p":"Jeder Full Node bedient dieselben Leserouten auf Port 8645. Richte deinen Code auf <code>http://127.0.0.1:8645</code>, dann hängst du an niemandes Server.","dev.api.n3.h":"Beträge sind ganze Zahlen","dev.api.n3.p":"Beträge kommen in Einheiten: 1 YSR sind 100.000.000 Einheiten. Lies sie als Ganzzahlen oder Zeichenketten, nie als Gleitkommazahlen.","dev.docs.h":"Die Dokumente","dev.docs.p":"Geschrieben für Menschen, die die Aussagen prüfen wollen. Jedes verweist auf den Code, den es beschreibt.","dev.docs.v6":"Die verbindliche Spezifikation der Fassung 6, aktiv ab Block 10.000.","dev.docs.fullnode":"Der Kommandozeilen-Full-Node: Befehle, Optionen, HTTP-Schnittstelle, Speicher und Reorganisationen.","dev.docs.p2p":"Das Protokoll, das Knoten miteinander sprechen.","dev.docs.fees":"Die Gebührenregeln und wie die Gebührenschätzung entsteht.","dev.docs.pool":"Pools: einem beitreten, einen betreiben, wie die Abrechnung funktioniert.","dev.docs.ops":"Die öffentliche Infrastruktur: Hauptknoten, HTTPS, Spiegel und seine Einstellungen.","dev.repo.h":"Was wo liegt","dev.repo.p":"Ein Repository enthält den Konsens-Code, den Knoten, den Miner und die Tests, die sie absichern.","dev.repo.core":"Konsens: Kopf, Difficulty, Transaktionen, Zustand, Wallet-Ableitung","dev.repo.fullnode":"Full Node: Kette, Mempool, Mining-Schnittstelle, Lese-API, Kommandozeile","dev.repo.p2p":"Das Protokoll zwischen den Knoten","dev.repo.pool":"PPLNS-Abrechnung und die Aufteilung der Blockbelohnung","dev.repo.node":"Bau des Kommandozeilen-Full-Node","dev.repo.nodecore":"Node Core für Windows und Linux, mit den GPU-Minern","dev.repo.miner":"Der Kommandozeilen-Miner, ohne Abhängigkeiten","dev.repo.observer":"Der Beobachter: ein kleines, nur lesendes Werkzeug, das die Kette lädt und jeden Block nachrechnet","dev.repo.tests":"Tests für Konsens, Knoten, P2P, Pool und Wallet","dev.repo.docs":"Die oben genannte Dokumentation","dev.repo.c1":"Im Wurzelordner des Repositorys: installieren, Tests ausführen, Typen prüfen","dev.sign.h":"Signierte Nachrichten","dev.sign.p":"Eine Wallet kann beweisen, dass sie eine Adresse kontrolliert, ohne einen Coin zu bewegen. Alle YSKAR-Programme signieren und prüfen dasselbe Textformat.","dev.sign.1":"Die Unterschrift ist Ed25519 über die rohen UTF-8-Bytes der ganzen Nachricht, geprüft nach derselben Regel wie in der Kette.","dev.sign.2":"Die erste Zeile macht es sicher: Eine Transaktion ist binär und beginnt nie mit diesen Wörtern, eine signierte Nachricht kann also nie als Überweisung gelten.","dev.sign.3":"YSKAR Wallet und Node Core signieren solche Nachrichten. YSKAR Lab meldet dich damit ohne Passwort an.","dev.con.h":"Mitarbeiten und melden","dev.con.1.h":"Änderungen am Code","dev.con.1.p":"<a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> nennt die Prüfungen, die vor einem Push bestehen müssen: die Typprüfungen und die ganze Testreihe.","dev.con.2.h":"Ideen und Vorschläge","dev.con.2.p":"Vorschläge für Protokoll und Software werden offen im <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a> besprochen. Du meldest dich mit deiner Wallet an.","dev.con.3.h":"Sicherheitsprobleme","dev.con.3.p":"Melde sie als Issue unter <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a>. Issues sind öffentlich: Beschreibe, was du gesehen hast und wie es sich nachstellen lässt, und poste nie deine 12 Wörter, eine PIN, eine Wallet-Datei oder einen Schlüssel.","ysr.now.blocks":"Blöcke","ysr.bar.circ":"Im Umlauf","ysr.bar.burned":"Verbrannt","ysr.bar.open":"Noch nicht ausgegeben","ysr.bar.cap":"Anteile an den 21.000.000 YSR, die es je geben kann.","ysr.sched.title":"Ausgabe nach Blockhöhe","ysr.sched.series":"ausgegeben","ysr.sched.when.past":"bereits gefunden","ysr.sched.when.future":"um den {date}, bei 600 s je Block","ysr.t.all":"Alle 37 Ären zeigen","ysr.t.less":"Die ersten 8 Ären zeigen","ysr.t.now":"jetzt","ysr.fees.h":"Gebühren","ysr.fees.p":"Eine Überweisung zahlt eine Gebühr an die Miner des Blocks, der sie aufnimmt. Die Regeln setzen nur eine Untergrenze. Darüber richtet sich der Preis nach der Nachfrage nach Platz im Block.","ysr.fees.f1":"Untergrenze laut Konsens","ysr.fees.f1.v":"1 Einheit je Byte","ysr.fees.f2":"Untergrenze für die Weiterleitung","ysr.fees.f2.v":"10 Einheiten je Byte. Das ist eine Einstellung der Knoten, keine Konsensregel.","ysr.fees.f3":"Eine einfache Überweisung mit 168 Byte","ysr.fees.f3.v":"mindestens, im Moment","ysr.fees.f4":"Langsam, normal, schnell","ysr.fees.f4.v":"Die drei Stufen unterscheiden sich nur, wenn Blöcke voll sind. Sonst genügt die Mindestgebühr für den nächsten Block.","ysr.fees.f5":"Kleinster Betrag","ysr.fees.f5.v":"100 Einheiten, also 0,000001 YSR","ysr.fees.f6":"Überweisungen, die auf einen Block warten","ysr.noprice.h":"Kein Preis, kein Versprechen","ysr.noprice.p1":"YSR hat keinen Preis und keinen Markt und ist an keiner Börse gelistet. Nichts auf dieser Seite verspricht, dass sich das ändert, und niemand sollte in dieser Erwartung minen.","ysr.noprice.p2":"Was YSR hat, ist ein Regelwerk, das jeder nachprüfen kann: eine feste Höchstmenge, ein öffentlicher Ausgabeplan und Coins, die nur der Schlüssel ihres Besitzers bewegen kann.","tech.header.h":"Ein Block beginnt mit 136 Byte","tech.header.p1":"Der Kopf nennt den Block davor, legt jede Transaktion und jedes Guthaben nach dem Block fest und trägt die Nonce, die der Miner gefunden hat. Der Blockhash ist zweimal SHA-256 über genau diese Bytes.","tech.header.p2":"Die Länge ist Absicht. SHA-256 arbeitet in Blöcken zu 64 Byte, und alles außer der Nonce liegt in den ersten 128. Ein Miner rechnet diesen Teil einmal je Auftrag; jeder weitere Versuch kostet zwei Kompressionsschritte.","tech.pow.h":"Arbeit, die jeder nachprüfen kann","tech.pow.p1":"Ein Block ist nur gültig, wenn sein Hash, als Zahl gelesen, nicht größer ist als ein Ziel. Das Ziel folgt aus der Difficulty. Eine Abkürzung gibt es nicht: Einen solchen Hash findet nur, wer Nonces durchprobiert, und das Ergebnis zu prüfen kostet zwei Hash-Berechnungen.","tech.pow.p2":"Eine Einheit Difficulty steht für 65.536 erwartete Versuche. Bei der aktuellen Difficulty von <span class='mono' data-live='difficulty'></span> braucht das Netz etwa <span data-live='attempts'></span> Versuche für einen Block.","tech.diff.h":"Die Difficulty folgt dem Netz","tech.diff.p1":"Die Difficulty wird für jeden Block aus den letzten 45 Blöcken neu berechnet. Jüngere Blöcke zählen mehr als ältere, deshalb reagiert die Kette schnell, wenn Rechenleistung dazukommt oder wegfällt.","tech.diff.p2":"Jeder Knoten berechnet aus denselben Blöcken denselben Bereich und lehnt einen Block ab, der eine Difficulty außerhalb davon angibt. Gerechnet wird nur mit ganzen Zahlen, damit zwei Knoten nie unterschiedlich runden.","tech.diff.chart":"Difficulty seit Block 1","tech.diff.cap":"Mittel über je 24 Blöcke bis Block <span data-live='snapTip'></span>. Die Skala ist logarithmisch: Jede Linie ist das Zehnfache der darunter.","tech.diff.f1":"Fenster","tech.diff.f1.v":"die letzten 45 Blöcke, die neuesten am stärksten gewichtet","tech.diff.f2":"Größter Schritt","tech.diff.f2.v":"Faktor 4 nach oben oder unten je Block","tech.diff.f3":"Gezählte Lösungszeit","tech.diff.f3.v":"1 bis 3.600 Sekunden je Block","tech.diff.f4":"Notfallregel","tech.diff.f4.v":"nach 1.800 Sekunden ohne Block sinkt die Anforderung im Verhältnis zur Wartezeit","tech.diff.f5":"Zeitstempel","tech.diff.f5.v":"später als der Median der letzten 11 Blöcke, höchstens 120 Sekunden vor der Uhr des Knotens","tech.acc.h":"Konten und Überweisungen","tech.acc.p1":"YSKAR führt je Adresse ein Guthaben und eine Nonce. Eine Überweisung nennt Absender, Empfänger, Betrag und Gebühr und ist mit dem Schlüssel des Absenders signiert. Ohne diesen Schlüssel kann niemand die Coins bewegen.","tech.acc.p2":"Die Zustandswurzel in jedem Kopf legt alle Guthaben fest. Ein Knoten, der die Kette ab Block 0 nachspielt, kommt auf dieselben Guthaben wie jeder andere, oder er lehnt den Block ab.","tech.tx.title":"Eine Überweisung, 168 Byte","tech.tx.p":"Dazu auf Wunsch eine Notiz von bis zu 32 Byte. Größen in Byte.","tech.tx.aria":"Die Felder einer Überweisung und ihre Größen in Byte","tech.tx.f1":"Version und Typ","tech.tx.f2":"Adresse des Absenders","tech.tx.f3":"Adresse des Empfängers","tech.tx.f4":"Betrag","tech.tx.f5":"Gebühr","tech.tx.f6":"Nonce des Absenders","tech.tx.f7":"Ablaufhöhe und Länge der Notiz","tech.tx.f8":"Öffentlicher Schlüssel","tech.tx.f9":"Signatur","tech.acc.f1":"Nur einmal gültig","tech.acc.f1.v":"Die Nonce muss genau der Zahl der bisherigen Überweisungen des Absenders entsprechen. Dieselbe Überweisung lässt sich deshalb nie zweimal anwenden.","tech.acc.f2":"An dieses Netz gebunden","tech.acc.f2.v":"Die Signatur umfasst die Chain-ID. Eine für YSKAR signierte Überweisung ist nirgendwo sonst gültig.","tech.acc.f3":"Ablauf","tech.acc.f3.v":"Der Absender kann eine letzte Blockhöhe nennen. Danach kann die Überweisung nie mehr aufgenommen werden.","tech.acc.f4":"Notiz","tech.acc.f4.v":"Bis zu 32 Byte, öffentlich in der Kette gespeichert.","tech.acc.f5":"Mindestgebühr","tech.acc.f5.v":"1 Einheit je Byte laut Konsens. Knoten leiten ab 10 Einheiten je Byte weiter. Gebühren gehen an die Miner des Blocks.","tech.acc.f6":"Eine einfache Überweisung kostet","tech.acc.f6.v":"im Moment mindestens","tech.key.aria":"Von 12 Wörtern zur Adresse","tech.key.1":"Wörter","tech.key.2":"Ableitungspfad","tech.key.3":"Schlüsselpaar","tech.key.4":"Adresse","tech.key.p":"Eine Wallet sind 12 oder 24 Wörter (BIP39). Daraus wird auf dem Gerät der Schlüssel abgeleitet (SLIP-0010), und die Adresse sind die ersten 20 Byte des SHA-256-Hashes des öffentlichen Schlüssels, geschrieben in bech32m. Die Wörter verlassen das Gerät nie, auf dem sie entstanden sind.","tech.nodes.h":"Jeder Knoten prüft jeden Block","tech.nodes.p1":"Ein Full Node speichert die ganze Kette und nimmt einen Block erst an, wenn er ihn vollständig geprüft hat, egal ob der Block von einem anderen Knoten kommt oder vom eigenen Miner. Die Prüfungen laufen in dieser Reihenfolge.","tech.nodes.link":"Einen Full Node betreiben","tech.check.1":"Version, höchstens 2.000 Transaktionen, genau eine Belohnungstransaktion an erster Stelle und die Transaktionswurzel.","tech.check.2":"Der zweifache Hash des Kopfs ist nicht größer als das Ziel der angegebenen Difficulty.","tech.check.3":"Die Höhe ist die des Vorgängers plus eins, und der Hash des Vorgängers stimmt.","tech.check.4":"Später als der Median der letzten 11 Blöcke, nicht vor dem Vorgänger und höchstens 120 Sekunden vor der Uhr des Knotens.","tech.check.5":"Die angegebene Difficulty liegt in dem Bereich, der aus den vorigen Blöcken folgt.","tech.check.6":"Signatur, Absender, Nonce, Guthaben, Gebühr und Ablauf jeder Überweisung. Die Belohnungstransaktion zahlt genau die Blockbelohnung plus die Gebühren aus.","tech.check.7":"Die Wurzel über alle Konten nach dem Block stimmt mit der Zustandswurzel im Kopf überein.","tech.nodes.chain.h":"Welche Kette zählt","tech.nodes.chain.p":"Die gültige Kette mit der meisten angesammelten Arbeit, wobei die Arbeit eines Blocks seine Difficulty ist. Ein Knoten bewahrt konkurrierende Blöcke auf und wechselt, wenn ein anderer Zweig mehr Arbeit hat.","tech.nodes.pool.h":"Pools ohne Verwahrung","tech.nodes.pool.p":"Die Belohnungstransaktion eines Blocks darf bis zu 64 Adressen auszahlen. Die Abrechnung eines Pools wird zu dieser Transaktion: Die Kette zahlt jeden Miner direkt aus, und der Betreiber hält nie fremde Coins. <a href='/mining#pools'>So funktionieren Pools</a>","tech.rev.h":"Regeln ändern sich an einer Blockhöhe","tech.rev.p":"Eine Regeländerung steht zusammen mit der Höhe im Code, ab der sie gilt. Jeder Knoten schaltet am selben Block um, und jeder Block unterhalb dieser Höhe behält seine Regeln, Byte für Byte.","tech.rev.c1":"Fassung","tech.rev.c2":"Ab Block","tech.rev.c3":"Änderung","tech.rev.c4":"Stand","tech.rev.2":"Die Belohnungstransaktion darf mehrere Adressen auszahlen. Darauf bauen die Pools auf.","tech.rev.3":"Eine Mindestgebühr je Byte ersetzt die feste Gebühr, und es gilt ein kleinster Betrag.","tech.rev.4":"Das Difficulty-Feld kann beliebig große Werte aufnehmen.","tech.rev.5":"Strengere Regeln für Zeitstempel, Block-Kodierung und Belohnungstransaktion.","tech.rev.6":"Gemeinsame Konten, Zeit- und Hash-Sperren, Sammelzahlungen, ein neuer Zustandsbaum und höhere Grenzen.","tech.rev.note":"Die Fassungen 2 bis 5 haben Regeln korrigiert und verschärft. Fassung 6 ist die erste, die Fähigkeiten hinzufügt, und die erste, der ältere Knoten nicht folgen können.","tech.v6.h":"Fassung 6","tech.v6.p":"Die nächste Regeländerung beginnt mit Block 10.000. Die Community hat diese Höhe am 25. Oktober 2026 in einer Abstimmung gewählt. Sie ändert den Kontoeintrag, das Adressformat und das Transaktionsformat, damit Konten mehr können, als ein Guthaben zu halten.","tech.v6.count":"Block 10.000","tech.v6.spec":"Die Spezifikation der Fassung 6 lesen","tech.v6.1.h":"Gemeinsame Konten","tech.v6.1.p":"Konten, die mehrere Signaturen zum Ausgeben brauchen, zum Beispiel 2 von 3, mit bis zu 16 Schlüsseln. Für gemeinsames Geld und sichereres Sparen.","tech.v6.2.h":"Zeitsperren","tech.v6.2.p":"YSR, die erst ab einer gewählten Blockhöhe ausgegeben werden können.","tech.v6.3.h":"Hash-Sperren","tech.v6.3.p":"Eine Zahlung wird nur gegen ein Geheimnis freigegeben und geht nach einer festen Höhe an den Absender zurück. Zwei Parteien können tauschen, ohne einander zu vertrauen.","tech.v6.4.h":"Sammelzahlungen","tech.v6.4.p":"Eine Transaktion zahlt bis zu 1.000 Empfänger auf einmal aus.","tech.v6.5.h":"Mehr Platz je Block","tech.v6.5.p":"Bis zu 5.000 Transaktionen je Block statt 2.000, und der Block eines Pools kann bis zu 255 Adressen auszahlen statt 64.","tech.v6.6.h":"Ein Fundament für später","tech.v6.6.p":"Ein Zustandsbaum, der für viele tausend Konten ausgelegt ist, Adressen mit Version und eine Fork-Kennung in jeder Signatur.","tech.v6.same.h":"Was gleich bleibt","tech.v6.same.1":"21 Millionen YSR und der Halbierungsplan","tech.v6.same.2":"10-Minuten-Blöcke, SHA-256 und die Difficulty-Regeln","tech.v6.same.3":"Jede Adresse, jeder Schlüssel und jedes Guthaben","tech.v6.do.h":"Was du tun musst","tech.v6.do.1":"Wallet und Knoten vor Block 10.000 aktualisieren","tech.v6.do.2":"Miner, GPU-Miner und das HiveOS-Paket brauchen kein Update","tech.v6.do.3":"Eine veraltete Wallet empfängt weiter YSR. Senden kann sie erst wieder nach dem Update","tech.lim.h":"Bekannte Grenzen","tech.lim.p":"Wogegen das System heute nicht schützt. Die Liste stammt aus dem Sicherheitsdokument des Projekts.","tech.lim.link":"Das vollständige Sicherheitsmodell","tech.lim.1.h":"Ein kleines Netz","tech.lim.1.p":"Das Netz hat zwei Seed-Knoten, beide vom selben Betreiber. Proof of Work schützt eine Kette nur, solange niemand allein den Großteil der Rechenleistung kontrolliert, und Rechenleistung, die über einen Pool mint, wird vom Betreiber dieses Pools gelenkt.","tech.lim.2.h":"Keine Checkpoints","tech.lim.2.p":"Ein Knoten wechselt zu jeder gültigen Kette mit mehr Arbeit, egal wie weit zurück sie abzweigt. Eine Überweisung gilt als umso endgültiger, je mehr Blöcke auf ihr aufbauen.","tech.lim.3.h":"Die Datenquelle des Explorers","tech.lim.3.p":"Explorer und Apps lesen aus einem Spiegel, einer Datenbankkopie der Kette für schnelles Laden. Er ist ein Komfort, nicht die Autorität: Die Kette ist das, worauf sich die Full Nodes einigen.","tech.lim.4.h":"Pool-Plätze","tech.lim.4.p":"Ein Pool hat höchstens 64 Plätze, mit Gebühr 63; ab Fassung 6 sind es 255 und 254. Eine Sitzung zu öffnen braucht nur eine gültige Adresse, Plätze lassen sich also billig belegen.","tech.lim.5.h":"Offene Schnittstellen","tech.lim.5.p":"Die HTTP-Schnittstelle eines Knotens begrenzt Anfragen je Client nicht. Bei einem öffentlichen Knoten muss das ein Reverse Proxy übernehmen.","tech.docs.1":"Die Protokoll-Spezifikation: Formate, Hashing, Difficulty, Gültigkeitsregeln und Testvektoren.","tech.docs.3":"Was Kryptografie und Konsens durchsetzen, wem man vertrauen muss, und die bekannten Grenzen.","miner.title":"Selbst nach einer Nonce suchen","miner.state":"Läuft in deinem Browser","miner.intro":"Dein Browser nimmt den Kopf des neuesten Blocks und probiert Nonces gegen ein leichteres Ziel. Das echte Ziel liegt weit jenseits dessen, was ein Browser schafft.","miner.bits":"Null-Bits, mit denen der Hash beginnen muss","miner.odds":"{b} Bits: etwa 1 Hash von {n}","miner.start":"Suche starten","miner.stop":"Stoppen","miner.attempts":"Versuche","miner.speed":"Tempo","miner.time":"Zeit","miner.nonce":"Gefundene Nonce","miner.hash":"Zuletzt probierter Hash","miner.hashFound":"Gefundener Hash","miner.target":"Ziel dieser Demo","miner.found":"Gefunden nach {n} Versuchen.","miner.none":"Kein Hash unter dem Ziel in {n} Versuchen. Starte erneut oder verlange weniger Null-Bits.","miner.stopped":"Gestoppt nach {n} Versuchen.","miner.real":"Mit {r} bräuchte dieser Browser im Mittel etwa {t}, um bei der heutigen Difficulty einen echten Block zu finden.","field.version":"Version","field.version.d":"Die Version des Kopfs. Heute 1, mit Konsensfassung 6 wird sie 6.","field.height":"Höhe","field.height.d":"Die Nummer dieses Blocks, gezählt ab Block 0.","field.prev":"Hash des Vorgängers","field.prev.d":"Der Hash des Blocks davor. Er verkettet die Blöcke: Wer einen alten Block ändert, ändert jeden Hash danach.","field.merkle":"Transaktionswurzel","field.merkle.d":"Ein Hash über alle Transaktionen im Block. Ein einziges geändertes Byte in einer davon ändert ihn.","field.state":"Zustandswurzel","field.state.d":"Ein Hash über alle Guthaben und Nonces nach diesem Block. Jeder Knoten berechnet ihn selbst und vergleicht.","field.time":"Zeitstempel","field.time.d":"Wann der Miner den Block gebaut hat. Er muss später liegen als der Median der letzten 11 Blöcke.","field.diff":"Difficulty","field.diff.d":"Wie schwer dieser Block sein musste. Daraus folgt das Ziel: 2^240 geteilt durch die Difficulty.","field.count":"Anzahl Transaktionen","field.count.d":"Wie viele Transaktionen der Block enthält, einschließlich der, die die Belohnung auszahlt.","field.extra":"Extranonce","field.extra.d":"Ein Wert, den der Knoten jedem Miner gibt, damit zwei Miner nie dieselben Köpfe durchsuchen.","field.nonce":"Nonce","field.nonce.d":"Die Zahl, die der Miner verändert hat, bis der Hash unter dem Ziel lag. Zwischen zwei Versuchen ändert sich sonst nichts.","proof.fixedBlock":"Steht in der Kette fest","proof.block":"Block {h}","proof.found":"gefunden {ago}","proof.fixed":"Unverändert seit 9. Sep. 2026","proof.cap":"Der Blockkopf: 136 Byte in zehn Feldern.","proof.bytesLabel":"Die 136 Byte des Kopfs von Block {h}, hexadezimal","proof.range":"Byte {a} bis {b}","proof.first":"SHA-256 der 136 Byte","proof.hash":"Zweimal SHA-256: der Blockhash","proof.target":"Ziel bei Difficulty {d}","proof.valid":"Gültig. Der Hash liegt unter dem Ziel.","proof.invalid":"Nicht gültig. Der Hash liegt über dem Ziel.","proof.time":"In deinem Browser berechnet in {ms} ms.","proof.again":"Erneut prüfen","proof.genesis":"Block 0 prüfen","proof.latest":"Neuesten Block prüfen","proof.open":"Diesen Block im Explorer öffnen","check.1":"Aufbau","check.2":"Proof of Work","check.3":"Platz in der Kette","check.4":"Zeitstempel","check.5":"Difficulty","check.6":"Jede Transaktion","check.7":"Zustandswurzel","chart.asTable":"Werte als Tabelle zeigen","chart.total":"gesamt","chart.height":"Bis Block","n.2000":"2.000","n.4000":"4.000","n.6000":"6.000","n.7000":"7.000","n.10000":"10.000","rev.active":"aktiv seit {date}","rev.set":"festgelegt, noch {n} Blöcke","ms.done":"aktiv","home.how.1.h":"Miner suchen","home.how.1.p":"Handys, PCs und Grafikkarten hashen einen Blockkopf immer wieder, jedes Mal mit einer anderen Nonce. Liegt ein Hash unter dem Ziel, ist der Block gültig.","home.how.2.h":"Knoten prüfen","home.how.2.p":"Jeder Full Node rechnet die Arbeit, die Signaturen und alle Guthaben nach, beginnend bei Block 0. Ein Block, der eine Regel bricht, wird abgelehnt, egal von wem er kommt.","home.how.3.h":"Der Block zahlt aus","home.how.3.p":"Der Block selbst zahlt die Belohnung aus: an den Finder allein oder aufgeteilt auf die Miner eines Pools, direkt an ihre Adressen. Ein Pool hält nie fremde Coins.","dev.api.down":"Die Anfrage ist fehlgeschlagen ({why}). Die API antwortet von hier aus gerade nicht."};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("de");
